export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-matplotlib-path-and-patch-manipulation":{"intro":"This tutorial will guide you through the process of drawing and manipulating shapes using the matplotlib.path.Path, matplotlib.patches.PathPatch, and matplotlib.transforms classes. You will learn how to create a plot with a circle, a dolphin shape, and a dolphin shape rotated by 60 degrees.","steps":[{"title":"Create a Circle","body":["First, let's create a circle in a plot using Circle and imshow functions. The imshow function is used to display an image in a plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.cm as cm\nfrom matplotlib.patches import Circle\n\nr = np.random.rand(50)\nt = np.random.rand(50) * np.pi * 2.0\nx = r * np.cos(t)\ny = r * np.sin(t)\n\nfig, ax = plt.subplots(figsize=(6, 6))\ncircle = Circle((0, 0), 1, facecolor='none',\n                edgecolor=(0, 0.8, 0.8), linewidth=3, alpha=0.5)\nax.add_patch(circle)\n\nim = plt.imshow(np.random.random((100, 100)),\n                origin='lower', cmap=cm.winter,\n                interpolation='spline36',\n                extent=([-1, 1, -1, 1]))\nim.set_clip_path(circle)\n\nplt.plot(x, y, 'o', color=(0.9, 0.9, 1.0), alpha=0.8)\nplt.show()"}]},{"title":"Create a Dolphin Shape","body":["Next, we will create a dolphin shape using Path and PathPatch functions. We will use the path of a dolphin shape from OpenClipart library by Andy Fitzsimon."],"code":[{"lang":"python","text":"from matplotlib.path import Path\nfrom matplotlib.patches import PathPatch\nimport numpy as np\n\ndolphin = \"\"\"\nM -0.59739425,160.18173 C -0.62740401,160.18885 -0.57867129,160.11183\n-0.57867129,160.11183 C -0.57867129,160.11183 -0.5438361,159.89315\n-0.39514638,159.81496 C -0.24645668,159.73678 -0.18316813,159.71981\n-0.18316813,159.71981 C -0.18316813,159.71981 -0.10322971,159.58124\n-0.057804323,159.58725 C -0.029723983,159.58913 -0.061841603,159.60356\n-0.071265813,159.62815 C -0.080250183,159.65325 -0.082918513,159.70554\n-0.061841203,159.71248 C -0.040763903,159.7194 -0.0066711426,159.71091\n0.077336307,159.73612 C 0.16879567,159.76377 0.28380306,159.86448\n0.31516668,159.91533 C 0.3465303,159.96618 0.5011127,160.1771\n0.5011127,160.1771 C 0.63668998,160.19238 0.67763022,160.31259\n0.66556395,160.32668 C 0.65339985,160.34212 0.66350443,160.33642\n0.64907098,160.33088 C 0.63463742,160.32533 0.61309688,160.297\n0.5789627,160.29339 C 0.54348657,160.28968 0.52329693,160.27674\n0.50728856,160.27737 C 0.49060916,160.27795 0.48965803,160.31565\n0.46114204,160.33673 C 0.43329696,160.35786 0.4570711,160.39871\n0.43309565,160.40685 C 0.4105108,160.41442 0.39416631,160.33027\n0.3954995,160.2935 C 0.39683269,160.25672 0.43807996,160.21522\n0.44567915,160.19734 C 0.45327833,160.17946 0.27946869,159.9424\n-0.061852613,159.99845 C -0.083965233,160.0427 -0.26176109,160.06683\n-0.26176109,160.06683 C -0.30127962,160.07028 -0.21167141,160.09731\n-0.24649368,160.1011 C -0.32642366,160.11569 -0.34521187,160.06895\n-0.40622293,160.0819 C -0.467234,160.09485 -0.56738444,160.17461\n-0.59739425,160.18173\n\"\"\"\n\nvertices = []\ncodes = []\nparts = dolphin.split()\ni = 0\ncode_map = {\n    'M': Path.MOVETO,\n    'C': Path.CURVE4,\n    'L': Path.LINETO,\n}\n\nwhile i < len(parts):\n    path_code = code_map[parts[i]]\n    npoints = Path.NUM_VERTICES_FOR_CODE[path_code]\n    codes.extend([path_code] * npoints)\n    vertices.extend([[*map(float, y.split(','))]\n                     for y in parts[i + 1:][:npoints]])\n    i += npoints + 1\nvertices = np.array(vertices)"}]},{"title":"Rotate the Dolphin Shape","body":["We will rotate the dolphin shape by 60 degrees using Affine2D().rotate_deg() function."],"code":[{"lang":"python","text":"from matplotlib.transforms import Affine2D\n\nvertices = Affine2D().rotate_deg(60).transform(vertices)\ndolphin_path2 = Path(vertices, codes)\ndolphin_patch2 = PathPatch(dolphin_path2, facecolor=(0.5, 0.5, 0.5),\n                           edgecolor=(0.0, 0.0, 0.0))\nax.add_patch(dolphin_patch2)"}]},{"title":"Finalize the Plot","body":["Let's put everything together and finalize the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.cm as cm\nfrom matplotlib.patches import Circle, PathPatch\nfrom matplotlib.path import Path\nfrom matplotlib.transforms import Affine2D\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nr = np.random.rand(50)\nt = np.random.rand(50) * np.pi * 2.0\nx = r * np.cos(t)\ny = r * np.sin(t)\n\nfig, ax = plt.subplots(figsize=(6, 6))\ncircle = Circle((0, 0), 1, facecolor='none',\n                edgecolor=(0, 0.8, 0.8), linewidth=3, alpha=0.5)\nax.add_patch(circle)\n\nim = plt.imshow(np.random.random((100, 100)),\n                origin='lower', cmap=cm.winter,\n                interpolation='spline36',\n                extent=([-1, 1, -1, 1]))\nim.set_clip_path(circle)\n\nplt.plot(x, y, 'o', color=(0.9, 0.9, 1.0), alpha=0.8)\n\ndolphin_path = Path(vertices, codes)\ndolphin_patch = PathPatch(dolphin_path, facecolor=(0.6, 0.6, 0.6),\n                          edgecolor=(0.0, 0.0, 0.0))\nax.add_patch(dolphin_patch)\n\nvertices = Affine2D().rotate_deg(60).transform(vertices)\ndolphin_path2 = Path(vertices, codes)\ndolphin_patch2 = PathPatch(dolphin_path2, facecolor=(0.5, 0.5, 0.5),\n                           edgecolor=(0.0, 0.0, 0.0))\nax.add_patch(dolphin_patch2)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.cm as cm\nfrom matplotlib.patches import Circle, PathPatch\nfrom matplotlib.path import Path\nfrom matplotlib.transforms import Affine2D\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nr = np.random.rand(50)\nt = np.random.rand(50) * np.pi * 2.0\nx = r * np.cos(t)\ny = r * np.sin(t)\n\nfig, ax = plt.subplots(figsize=(6, 6))\ncircle = Circle((0, 0), 1, facecolor='none',\n                edgecolor=(0, 0.8, 0.8), linewidth=3, alpha=0.5)\nax.add_patch(circle)\n\nim = plt.imshow(np.random.random((100, 100)),\n                origin='lower', cmap=cm.winter,\n                interpolation='spline36',\n                extent=([-1, 1, -1, 1]))\nim.set_clip_path(circle)\n\nplt.plot(x, y, 'o', color=(0.9, 0.9, 1.0), alpha=0.8)\n\ndolphin_path = Path(vertices, codes)\ndolphin_patch = PathPatch(dolphin_path, facecolor=(0.6, 0.6, 0.6),\n                          edgecolor=(0.0, 0.0, 0.0))\nax.add_patch(dolphin_patch)\n\nvertices = Affine2D().rotate_deg(60).transform(vertices)\ndolphin_path2 = Path(vertices, codes)\ndolphin_patch2 = PathPatch(dolphin_path2, facecolor=(0.5, 0.5, 0.5),\n                           edgecolor=(0.0, 0.0, 0.0))\nax.add_patch(dolphin_patch2)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-donuts-using-path-path-and-patches-":{"intro":"In this tutorial, we will create a donut using Matplotlib's ~.path.Path and ~.patches.PathPatch. We will use the make_circle() function to create the circle and concatenate the inside and outside subpaths together to create the donut.","steps":[{"title":"Importing Necessary Libraries","body":["We will start by importing the necessary libraries for this tutorial."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.patches as mpatches\nimport matplotlib.path as mpath"}]},{"title":"Defining Helper Function","body":["We will define a helper function wise() to determine the orientation of the path."],"code":[{"lang":"python","text":"def wise(v):\n    if v == 1:\n        return \"CCW\"\n    else:\n        return \"CW\""}]},{"title":"Creating the Circle","body":["We will create the circle using the make_circle() function. The function takes the radius of the circle as input and returns the x and y coordinates of the circle."],"code":[{"lang":"python","text":"def make_circle(r):\n    t = np.arange(0, np.pi * 2.0, 0.01)\n    t = t.reshape((len(t), 1))\n    x = r * np.cos(t)\n    y = r * np.sin(t)\n    return np.hstack((x, y))"}]},{"title":"Creating the Donut","body":["We will create the donut by concatenating the inside and outside subpaths together. We will use codes to specify the type of each vertex (MOVETO, LINETO, etc). We will then create a Path object using mpath.Path and a PathPatch object using mpatches.PathPatch. We will finally add the PathPatch object to the Axes object using ax.add_patch()."],"code":[{"lang":"python","text":"Path = mpath.Path\nfig, ax = plt.subplots()\n\ninside_vertices = make_circle(0.5)\noutside_vertices = make_circle(1.0)\ncodes = np.ones(\n    len(inside_vertices), dtype=mpath.Path.code_type) * mpath.Path.LINETO\ncodes[0] = mpath.Path.MOVETO\n\nfor i, (inside, outside) in enumerate(((1, 1), (1, -1), (-1, 1), (-1, -1))):\n    # Concatenate the inside and outside subpaths together, changing their\n    # order as needed\n    vertices = np.concatenate((outside_vertices[::outside],\n                               inside_vertices[::inside]))\n    # Shift the path\n    vertices[:, 0] += i * 2.5\n    # The codes will be all \"LINETO\" commands, except for \"MOVETO\"s at the\n    # beginning of each subpath\n    all_codes = np.concatenate((codes, codes))\n    # Create the Path object\n    path = mpath.Path(vertices, all_codes)\n    # Add plot it\n    patch = mpatches.PathPatch(path, facecolor='#885500', edgecolor='black')\n    ax.add_patch(patch)\n\n    ax.annotate(f\"Outside {wise(outside)},\\nInside {wise(inside)}\",\n                (i * 2.5, -1.5), va=\"top\", ha=\"center\")\n\nax.set_xlim(-2, 10)\nax.set_ylim(-3, 2)\nax.set_title('Mmm, donuts!')\nax.set_aspect(1.0)\nplt.show()"}]},{"title":"Summary","body":["In this tutorial, we learned how to create a donut using Matplotlib's ~.path.Path and ~.patches.PathPatch. We used the make_circle() function to create the circle and concatenated the inside and outside subpaths together to create the donut. We also learned how to specify the type of each vertex and create a Path object using mpath.Path. Finally, we learned how to create a PathPatch object using mpatches.PathPatch and add it to the Axes object using ax.add_patch()."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-double-pendulum-simulation":{"intro":"The double pendulum is a classic problem in physics and mathematics. It involves two pendulums attached to each other, and the motion of the second pendulum is affected by the motion of the first pendulum. In this lab, we will use Python and Matplotlib to simulate the motion of a double pendulum.","steps":[{"title":"Import Required Libraries","body":["We will begin by importing the necessary libraries for our simulation."],"code":[{"lang":"python","text":"from collections import deque\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom numpy import cos, sin\nimport matplotlib.animation as animation"}]},{"title":"Set Up Parameters","body":["Next, we will define the parameters for our simulation. These parameters include the acceleration due to gravity, the length and mass of each pendulum, and the time interval for the simulation."],"code":[{"lang":"python","text":"G = 9.8  # acceleration due to gravity, in m/s^2\nL1 = 1.0  # length of pendulum 1 in m\nL2 = 1.0  # length of pendulum 2 in m\nL = L1 + L2  # maximal length of the combined pendulum\nM1 = 1.0  # mass of pendulum 1 in kg\nM2 = 1.0  # mass of pendulum 2 in kg\nt_stop = 2.5  # how many seconds to simulate\nhistory_len = 500  # how many trajectory points to display"}]},{"title":"Define the Derivatives Function","body":["Define the Derivatives Function","We will define a function that calculates the derivatives of the system at any given time. This function takes in the current state of the system (the angles and angular velocities of each pendulum) and returns the derivatives of those values."],"code":[{"lang":"python","text":"def derivs(t, state):\n    dydx = np.zeros_like(state)\n\n    dydx[0] = state[1]\n\n    delta = state[2] - state[0]\n    den1 = (M1+M2) * L1 - M2 * L1 * cos(delta) * cos(delta)\n    dydx[1] = ((M2 * L1 * state[1] * state[1] * sin(delta) * cos(delta)\n                + M2 * G * sin(state[2]) * cos(delta)\n                + M2 * L2 * state[3] * state[3] * sin(delta)\n                - (M1+M2) * G * sin(state[0]))\n               / den1)\n\n    dydx[2] = state[3]\n\n    den2 = (L2/L1) * den1\n    dydx[3] = ((- M2 * L2 * state[3] * state[3] * sin(delta) * cos(delta)\n                + (M1+M2) * G * sin(state[0]) * cos(delta)\n                - (M1+M2) * L1 * state[1] * state[1] * sin(delta)\n                - (M1+M2) * G * sin(state[2]))\n               / den2)\n\n    return dydx"}]},{"title":"Set Up Initial Conditions and Integrate the ODE","body":["Set Up Initial Conditions and Integrate the ODE","We will now set up the initial conditions for our simulation. We will set the initial angles and angular velocities of each pendulum, as well as the time interval for the simulation. We will then integrate the ODE using Euler's method to get the position and velocity of each pendulum at each time step."],"code":[{"lang":"python","text":"# create a time array from 0..t_stop sampled at 0.02 second steps\ndt = 0.01\nt = np.arange(0, t_stop, dt)\n\n# th1 and th2 are the initial angles (degrees)\n# w10 and w20 are the initial angular velocities (degrees per second)\nth1 = 120.0\nw1 = 0.0\nth2 = -10.0\nw2 = 0.0\n\n# initial state\nstate = np.radians([th1, w1, th2, w2])\n\n# integrate the ODE using Euler's method\ny = np.empty((len(t), 4))\ny[0] = state\nfor i in range(1, len(t)):\n    y[i] = y[i - 1] + derivs(t[i - 1], y[i - 1]) * dt"}]},{"title":"Calculate the Position of Each Pendulum","body":["Calculate the Position of Each Pendulum","We will now use the position and velocity of each pendulum at each time step to calculate the x and y coordinates of each pendulum."],"code":[{"lang":"python","text":"x1 = L1*sin(y[:, 0])\ny1 = -L1*cos(y[:, 0])\n\nx2 = L2*sin(y[:, 2]) + x1\ny2 = -L2*cos(y[:, 2]) + y1"}]},{"title":"Set Up the Plot","body":["We will now set up the plot for our simulation. We will create a figure with an x and y limit equal to the maximum length of the pendulum, set the aspect ratio to be equal, and add a grid."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(5, 4))\nax = fig.add_subplot(autoscale_on=False, xlim=(-L, L), ylim=(-L, 1.))\nax.set_aspect('equal')\nax.grid()"}]},{"title":"Define the Animation Function","body":["We will define a function that will animate the motion of the double pendulum. This function will take in the current time step and use it to update the position of each pendulum. It will also update the trajectory of the second pendulum."],"code":[{"lang":"python","text":"line, = ax.plot([], [], 'o-', lw=2)\ntrace, = ax.plot([], [], '.-', lw=1, ms=2)\ntime_template = 'time = %.1fs'\ntime_text = ax.text(0.05, 0.9, '', transform=ax.transAxes)\nhistory_x, history_y = deque(maxlen=history_len), deque(maxlen=history_len)\n\ndef animate(i):\n    thisx = [0, x1[i], x2[i]]\n    thisy = [0, y1[i], y2[i]]\n\n    if i == 0:\n        history_x.clear()\n        history_y.clear()\n\n    history_x.appendleft(thisx[2])\n    history_y.appendleft(thisy[2])\n\n    line.set_data(thisx, thisy)\n    trace.set_data(history_x, history_y)\n    time_text.set_text(time_template % (i*dt))\n    return line, trace, time_text"}]},{"title":"Create the Animation","body":["We will now create the animation using the FuncAnimation function from Matplotlib."],"code":[{"lang":"python","text":"ani = animation.FuncAnimation(\n    fig, animate, len(y), interval=dt*1000, blit=True)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ani = animation.FuncAnimation(\n    fig, animate, len(y), interval=dt*1000, blit=True)\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-animated-images-with-matplotlib":{"intro":"In this lab, we will learn how to create an animated image using precomputed lists of images. We will be using the Matplotlib library in Python to create the animation. The purpose of this lab is to demonstrate the process of creating an animated image and to provide a basic understanding of how it works.","steps":[{"title":"Import Libraries","body":["To start, we need to import the libraries that we will be using. We will be using the Matplotlib library to create the animation and the Numpy library to generate the data for the animation."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.animation as animation"}]},{"title":"Create the Figure and Axes Objects","body":["Create the Figure and Axes Objects","Next, we need to create the figure and axes objects that we will be using to create the animation. We will be using the subplots method to create these objects."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Define the Function","body":["We now need to define the function that we will be using to generate the data for the animation. In this example, we will be using the sine and cosine functions to generate the data."],"code":[{"lang":"python","text":"def f(x, y):\n    return np.sin(x) + np.cos(y)"}]},{"title":"Generate the Data","body":["We will be using the linspace method from the Numpy library to generate the data for the animation. We will be generating two sets of data, x and y, and then reshaping the y data to create a two-dimensional array."],"code":[{"lang":"python","text":"x = np.linspace(0, 2 * np.pi, 120)\ny = np.linspace(0, 2 * np.pi, 100).reshape(-1, 1)"}]},{"title":"Create the Animation Frames","body":["We will now create the frames for the animation. We will be using a for loop to generate 60 frames. In each iteration of the loop, we will be updating the x and y data and then creating a new image object using the imshow method. We will then append the image object to the ims list."],"code":[{"lang":"python","text":"ims = []\nfor i in range(60):\n    x += np.pi / 15\n    y += np.pi / 30\n    im = ax.imshow(f(x, y), animated=True)\n    if i == 0:\n        ax.imshow(f(x, y))  # show an initial one first\n    ims.append([im])"}]},{"title":"Create the Animation","body":["We will now create the animation using the ArtistAnimation method. We will be passing in the figure object, the ims list, the interval between frames, and the repeat delay."],"code":[{"lang":"python","text":"ani = animation.ArtistAnimation(fig, ims, interval=50, blit=True, repeat_delay=1000)"}]},{"title":"Display the Animation","body":["Finally, we will use the show method to display the animation."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-ellipse-with-orientation-arrow":{"intro":"In this lab, you will learn how to draw an ellipse with an orientation arrow using Matplotlib. Ellipses are a type of shape that are commonly used in data visualization to represent data. By adding an orientation arrow to an ellipse, you can provide additional information about the direction of the data.","steps":[{"title":"Import Matplotlib and Create a Figure and Axis","body":["Import Matplotlib and Create a Figure and Axis","First, you need to import Matplotlib and create a figure and axis. The figure and axis are the containers for your plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# Create a figure and axis\nfig, ax = plt.subplots(subplot_kw={\"aspect\": \"equal\"})"}]},{"title":"Create an Ellipse","body":["Next, you need to create an ellipse using the Ellipse class. You can specify the center of the ellipse, the width and height of the ellipse, and the angle of rotation."],"code":[{"lang":"python","text":"from matplotlib.patches import Ellipse\n\nellipse = Ellipse(\n    xy=(2, 4),\n    width=30,\n    height=20,\n    angle=35,\n    facecolor=\"none\",\n    edgecolor=\"b\"\n)\nax.add_patch(ellipse)"}]},{"title":"Add an Orientation Arrow","body":["You can add an orientation arrow to the ellipse by plotting a marker at the end point of the minor axis. You can use the get_co_vertices() method to get the coordinates of the vertices of the ellipse. Then, you can use the Affine2D() class to rotate the marker to match the angle of the ellipse."],"code":[{"lang":"python","text":"from matplotlib.markers import MarkerStyle\nfrom matplotlib.transforms import Affine2D\n\n# Plot an arrow marker at the end point of minor axis\nvertices = ellipse.get_co_vertices()\nt = Affine2D().rotate_deg(ellipse.angle)\nax.plot(\n    vertices[0][0],\n    vertices[0][1],\n    color=\"b\",\n    marker=MarkerStyle(\">\", \"full\", t),\n    markersize=10\n)"}]},{"title":"Reverse the Orientation Arrow","body":["If you want to reverse the orientation arrow, you can switch the marker type from > to <."],"code":[{"lang":"python","text":"# To reverse the orientation arrow, switch the marker type from > to <.\nax.plot(\n    vertices[0][0],\n    vertices[0][1],\n    color=\"b\",\n    marker=MarkerStyle(\"<\", \"full\", t),\n    markersize=10\n)"}]},{"title":"Display the Plot","body":["Finally, you can display the plot using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-ellipse-collection":{"intro":"Matplotlib is a powerful data visualization library in Python. In this lab, we will explore the use of EllipseCollection to draw a collection of ellipses.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.collections import EllipseCollection"}]},{"title":"Create data for ellipses","body":["We create data for our ellipses in the form of arrays of x-coordinates, y-coordinates, width, height and angle."],"code":[{"lang":"python","text":"x = np.arange(10)\ny = np.arange(15)\nX, Y = np.meshgrid(x, y)\n\nXY = np.column_stack((X.ravel(), Y.ravel()))\n\nww = X / 10.0\nhh = Y / 15.0\naa = X * 9"}]},{"title":"Create Ellipse Collection","body":["We create an EllipseCollection with the above data and specify the units to be 'x' and the offsets to be XY."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nec = EllipseCollection(ww, hh, aa, units='x', offsets=XY,\n                       offset_transform=ax.transData)"}]},{"title":"Set the color of ellipses","body":["We set the color of each ellipse in the EllipseCollection based on the sum of its x and y coordinate."],"code":[{"lang":"python","text":"ec.set_array((X + Y).ravel())"}]},{"title":"Add collection to the plot","body":["We add the EllipseCollection to the plot."],"code":[{"lang":"python","text":"ax.add_collection(ec)\nax.autoscale_view()\nax.set_xlabel('X')\nax.set_ylabel('y')\ncbar = plt.colorbar(ec)\ncbar.set_label('X+Y')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax.add_collection(ec)\nax.autoscale_view()\nax.set_xlabel('X')\nax.set_ylabel('y')\ncbar = plt.colorbar(ec)\ncbar.set_label('X+Y')\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-drawing-ellipses-with-python-matplotlib":{"intro":"This lab demonstrates how to use Python Matplotlib to draw ellipses. The lab covers two examples:","steps":[{"title":"Importing Required Libraries","body":["First, we need to import the required libraries. We will use numpy to generate random data, and matplotlib.pyplot and matplotlib.patches to draw the ellipses."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.patches import Ellipse"}]},{"title":"Drawing Individual Ellipses","body":["In this example, we will draw many ellipses with random sizes, positions, and colors. Each ellipse will be an instance of the Ellipse class."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n# Number of ellipses to draw\nNUM = 250\n\n# Generate the ellipses\nells = [Ellipse(xy=np.random.rand(2) * 10,\n                width=np.random.rand(), height=np.random.rand(),\n                angle=np.random.rand() * 360)\n        for i in range(NUM)]\n\n# Create the plot and set the aspect ratio to 'equal'\nfig, ax = plt.subplots(subplot_kw={'aspect': 'equal'})\n\n# Add each ellipse to the plot\nfor e in ells:\n    ax.add_artist(e)\n    e.set_clip_box(ax.bbox)\n    e.set_alpha(np.random.rand())\n    e.set_facecolor(np.random.rand(3))\n\n# Set the x and y limits of the plot\nax.set_xlim(0, 10)\nax.set_ylim(0, 10)\n\n# Show the plot\nplt.show()"}]},{"title":"Drawing Ellipses with Different Angles","body":["Drawing Ellipses with Different Angles","In this example, we will draw many ellipses with different angles. We will use a loop to create an Ellipse instance for each angle we want to draw."],"code":[{"lang":"python","text":"# Define the angle step and the range of angles to draw\nangle_step = 45  # degrees\nangles = np.arange(0, 180, angle_step)\n\n# Create the plot and set the aspect ratio to 'equal'\nfig, ax = plt.subplots(subplot_kw={'aspect': 'equal'})\n\n# Loop over the angles and draw an ellipse for each angle\nfor angle in angles:\n    ellipse = Ellipse((0, 0), 4, 2, angle=angle, alpha=0.1)\n    ax.add_artist(ellipse)\n\n# Set the x and y limits of the plot\nax.set_xlim(-2.2, 2.2)\nax.set_ylim(-2.2, 2.2)\n\n# Show the plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Define the angle step and the range of angles to draw\nangle_step = 45  # degrees\nangles = np.arange(0, 180, angle_step)\n\n# Create the plot and set the aspect ratio to 'equal'\nfig, ax = plt.subplots(subplot_kw={'aspect': 'equal'})\n\n# Loop over the angles and draw an ellipse for each angle\nfor angle in angles:\n    ellipse = Ellipse((0, 0), 4, 2, angle=angle, alpha=0.1)\n    ax.add_artist(ellipse)\n\n# Set the x and y limits of the plot\nax.set_xlim(-2.2, 2.2)\nax.set_ylim(-2.2, 2.2)\n\n# Show the plot\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-ellipse-with-units":{"intro":"In this lab, you will learn how to compare the ellipse generated with arcs versus a polygonal approximation using Python Matplotlib.","steps":[{"title":"Import Libraries","body":["To begin, we will import the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib import patches"}]},{"title":"Set Ellipse Parameters","body":["In this step, we will set the parameters for the ellipse."],"code":[{"lang":"python","text":"xcenter, ycenter = 0.38, 0.52\nwidth, height = 0.1, 0.3\nangle = -30"}]},{"title":"Generate Ellipse using Arcs","body":["In this step, we will generate the ellipse using arcs."],"code":[{"lang":"python","text":"theta = np.deg2rad(np.arange(0.0, 360.0, 1.0))\nx = 0.5 * width * np.cos(theta)\ny = 0.5 * height * np.sin(theta)\n\nrtheta = np.radians(angle)\nR = np.array([\n    [np.cos(rtheta), -np.sin(rtheta)],\n    [np.sin(rtheta),  np.cos(rtheta)],\n    ])\n\nx, y = np.dot(R, [x, y])\nx += xcenter\ny += ycenter"}]},{"title":"Generate Ellipse using Polygonal Approximation","body":["Generate Ellipse using Polygonal Approximation","In this step, we will generate the ellipse using a polygonal approximation."],"code":[{"lang":"python","text":"theta = np.deg2rad(np.arange(0.0, 360.0, 1.0))\nx = 0.5 * width * np.cos(theta)\ny = 0.5 * height * np.sin(theta)\n\nrtheta = np.radians(angle)\nR = np.array([\n    [np.cos(rtheta), -np.sin(rtheta)],\n    [np.sin(rtheta),  np.cos(rtheta)],\n    ])\n\nx, y = np.dot(R, [x, y])\nx += xcenter\ny += ycenter"}]},{"title":"Plot Ellipse using Arcs","body":["In this step, we will plot the ellipse using arcs."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(211, aspect='auto')\nax.fill(x, y, alpha=0.2, facecolor='yellow',\n        edgecolor='yellow', linewidth=1, zorder=1)\n\ne1 = patches.Arc((xcenter, ycenter), width, height,\n                 angle=angle, linewidth=2, fill=False, zorder=2)\n\nax.add_patch(e1)"}]},{"title":"Plot Ellipse using Polygonal Approximation","body":["Plot Ellipse using Polygonal Approximation","In this step, we will plot the ellipse using a polygonal approximation."],"code":[{"lang":"python","text":"ax = fig.add_subplot(212, aspect='equal')\nax.fill(x, y, alpha=0.2, facecolor='green', edgecolor='green', zorder=1)\ne2 = patches.Arc((xcenter, ycenter), width, height,\n                 angle=angle, linewidth=2, fill=False, zorder=2)\n\nax.add_patch(e2)\nfig.savefig('arc_compare')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = fig.add_subplot(212, aspect='equal')\nax.fill(x, y, alpha=0.2, facecolor='green', edgecolor='green', zorder=1)\ne2 = patches.Arc((xcenter, ycenter), width, height,\n                 angle=angle, linewidth=2, fill=False, zorder=2)\n\nax.add_patch(e2)\nfig.savefig('arc_compare')\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-labeling-ticks-using-engineering-notation":{"intro":"In data visualization, it is essential to label the ticks on axes accurately. The EngFormatter in Matplotlib is a class that enables one to label the ticks on an axis using engineering notation. Engineering notation is a mathematical representation of numbers that uses powers of ten with a multiple of three. It is a concise way to express large or small numbers that are difficult to read or write in standard notation. In this lab, we will learn how to label ticks on an axis using engineering notation.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the required libraries. In this lab, we will use Matplotlib, NumPy, and EngFormatter."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.ticker import EngFormatter"}]},{"title":"Create Artificial Data","body":["We need to create some artificial data to plot. In this lab, we will plot the log of the frequency (in Hz) against the log of the power (in Watts). We will use the numpy library to generate the data."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nprng = np.random.RandomState(19680801)\n\n# Create artificial data to plot.\n# The x data span over several decades to demonstrate several SI prefixes.\nxs = np.logspace(1, 9, 100)\nys = (0.8 + 0.4 * prng.uniform(size=100)) * np.log10(xs)**2"}]},{"title":"Create the Figure and Subplots","body":["Create the Figure and Subplots","We need to create a figure and subplots to display the data. In this lab, we will create two subplots, side by side."],"code":[{"lang":"python","text":"# Figure width is doubled (2*6.4) to display nicely 2 subplots side by side.\nfig, (ax0, ax1) = plt.subplots(nrows=2, figsize=(7, 9.6))\nfor ax in (ax0, ax1):\n    ax.set_xscale('log')"}]},{"title":"Label the Ticks Using Engineering Notation","body":["Label the Ticks Using Engineering Notation","We will now label the ticks on the x-axis using engineering notation. In the first subplot, we will use the default settings, and in the second subplot, we will use the options places and sep to specify the number of digits after the decimal point and the separator between the number and the prefix/unit."],"code":[{"lang":"python","text":"# Demo of the default settings, with a user-defined unit label.\nax0.set_title('Full unit ticklabels, w/ default precision & space separator')\nformatter0 = EngFormatter(unit='Hz')\nax0.xaxis.set_major_formatter(formatter0)\nax0.plot(xs, ys)\nax0.set_xlabel('Frequency')\n\n# Demo of the options `places` (number of digit after decimal point) and\n# `sep` (separator between the number and the prefix/unit).\nax1.set_title('SI-prefix only ticklabels, 1-digit precision & '\n              'thin space separator')\nformatter1 = EngFormatter(places=1, sep=\"\\N{THIN SPACE}\")  # U+2009\nax1.xaxis.set_major_formatter(formatter1)\nax1.plot(xs, ys)\nax1.set_xlabel('Frequency [Hz]')"}]},{"title":"Display the Plot","body":["We will now display the plot using the plt.show() function."],"code":[{"lang":"python","text":"plt.tight_layout()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.tight_layout()\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-basic-errorbar-function":{"intro":"This tutorial will guide you through the basic usage of the errorbar() function in Matplotlib. The errorbar() function is used to plot error bars on a graph. Error bars indicate the variability or uncertainty of a data point in a graph. The function can be used to plot error bars in both the x- and y-directions.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries. In this example, we will be using matplotlib and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create example data","body":["Next, we will create example data to use in the graph. In this example, we will use the numpy.arange() function to create an array of values between 0.1 and 4 with a step of 0.5. We will then use the numpy.exp() function to calculate the exponential of each value in the array."],"code":[{"lang":"python","text":"# example data\nx = np.arange(0.1, 4, 0.5)\ny = np.exp(-x)"}]},{"title":"Plot the graph","body":["Now that we have our example data, we can plot the graph using the errorbar() function. We will pass in the x and y arrays as the first two parameters. We will then specify the error in the x-direction as 0.2 and the error in the y-direction as 0.4 using the xerr and yerr parameters, respectively."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.errorbar(x, y, xerr=0.2, yerr=0.4)\nplt.show()"}]},{"title":"Analyze the graph","body":["The resulting graph will display the y values as a function of the x values, with error bars indicating the variability in both directions. The x error bars will be 0.2 units long, and the y error bars will be 0.4 units long."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-error-bar-customization":{"intro":"In data visualization, error bars are a useful tool to display the uncertainty in the data. Error bars are graphical representations of the variability of data and are used on graphs to indicate the error or uncertainty in a reported measurement. In this lab, we will learn about the different ways of specifying error bars in Matplotlib.","steps":[{"title":"Import Libraries","body":["We will begin by importing the necessary libraries, including Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define Data","body":["Next, we will define our x and y data. In this example, we will use the np.arange() and np.exp() functions to create x and y data, respectively."],"code":[{"lang":"python","text":"# example data\nx = np.arange(0.1, 4, 0.5)\ny = np.exp(-x)"}]},{"title":"Define Error Values","body":["We will now define our error values. In this example, we will use the error variable to represent symmetric error and the asymmetric_error variable to represent asymmetric error."],"code":[{"lang":"python","text":"# example error bar values that vary with x-position\nerror = 0.1 + 0.2 * x\n\n# error bar values w/ different -/+ errors that\n# also vary with the x-position\nlower_error = 0.4 * error\nupper_error = error\nasymmetric_error = [lower_error, upper_error]"}]},{"title":"Plot Variable, Symmetric Error Bars","body":["Plot Variable, Symmetric Error Bars","We will now plot our data with variable, symmetric error bars. The ax.errorbar() function is used to create the plot, and the yerr parameter is used to specify the error values."],"code":[{"lang":"python","text":"# plot variable, symmetric error bars\nfig, ax = plt.subplots()\nax.errorbar(x, y, yerr=error, fmt='-o')\nax.set_title('Variable, Symmetric Error Bars')\nplt.show()"}]},{"title":"Plot Variable, Asymmetric Error Bars","body":["Plot Variable, Asymmetric Error Bars","Next, we will plot our data with variable, asymmetric error bars. The ax.errorbar() function is used again, but this time the xerr parameter is used to specify the asymmetric error values."],"code":[{"lang":"python","text":"# plot variable, asymmetric error bars\nfig, ax = plt.subplots()\nax.errorbar(x, y, xerr=asymmetric_error, fmt='o')\nax.set_title('Variable, Asymmetric Error Bars')\nplt.show()"}]},{"title":"Plot Log Scale with Error Bars","body":["Plot Log Scale with Error Bars","Finally, we will plot our data with a log scale and error bars. The ax.set_yscale() function is used to set the y-axis to a logarithmic scale."],"code":[{"lang":"python","text":"# plot log scale with error bars\nfig, ax = plt.subplots()\nax.errorbar(x, y, yerr=error, fmt='o')\nax.set_title('Log Scale with Error Bars')\nax.set_yscale('log')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# plot log scale with error bars\nfig, ax = plt.subplots()\nax.errorbar(x, y, yerr=error, fmt='o')\nax.set_title('Log Scale with Error Bars')\nax.set_yscale('log')\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-matplotlib-error-bar-plots":{"intro":"Error bars are used in graphs and charts to show the potential error or uncertainty in a measurement or data point. Python Matplotlib is a popular data visualization library that provides different types of error bar plots. In this lab, we will learn how to create error bar plots with upper and lower limits using Matplotlib.","steps":[{"title":"Import Required Libraries","body":["We will begin by importing the required libraries, including NumPy and Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define Data","body":["Next, we will define some example data to plot. Here, we will create an array of x-values, y-values, and their corresponding error values."],"code":[{"lang":"python","text":"x = np.array([0.5, 1.0, 1.5, 2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0])\ny = np.exp(-x)\nxerr = 0.1\nyerr = 0.2"}]},{"title":"Create Simple Error Bar Plot","body":["We will create a simple error bar plot with standard error bars using the errorbar function. Here, we will set the x and y values along with their corresponding error values. We will also set the line style to dotted."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(7, 4))\n\n# standard error bars\nax.errorbar(x, y, xerr=xerr, yerr=yerr, linestyle='dotted')"}]},{"title":"Add Upper Limits","body":["To add upper limits to the error bars, we will use the uplims parameter of the errorbar function. We will also add a constant value of 0.5 to the y-values to differentiate this plot from the previous one."],"code":[{"lang":"python","text":"# including upper limits\nax.errorbar(x, y + 0.5, xerr=xerr, yerr=yerr, uplims=True, linestyle='dotted')"}]},{"title":"Add Lower Limits","body":["To add lower limits to the error bars, we will use the lolims parameter of the errorbar function. We will also add a constant value of 1.0 to the y-values to differentiate this plot from the previous ones."],"code":[{"lang":"python","text":"# including lower limits\nax.errorbar(x, y + 1.0, xerr=xerr, yerr=yerr, lolims=True, linestyle='dotted')"}]},{"title":"Add Upper and Lower Limits","body":["To add both upper and lower limits to the error bars, we will use both the uplims and lolims parameters of the errorbar function. We will also add a marker to the plot to differentiate it from the previous ones."],"code":[{"lang":"python","text":"# including upper and lower limits\nax.errorbar(x, y + 1.5, xerr=xerr, yerr=yerr, lolims=True, uplims=True,\n            marker='o', markersize=8, linestyle='dotted')"}]},{"title":"Add Limits to Both X and Y Axes","body":["Add Limits to Both X and Y Axes","Finally, we will add limits to both the x and y axes. We will use the xlolims and xuplims parameters to add limits to the x-axis error bars."],"code":[{"lang":"python","text":"# Plot a series with lower and upper limits in both x & y\n# constant x-error with varying y-error\nxerr = 0.2\nyerr = np.full_like(x, 0.2)\nyerr[[3, 6]] = 0.3\n\n# mock up some limits by modifying previous data\nxlolims = lolims\nxuplims = uplims\nlolims = np.zeros_like(x)\nuplims = np.zeros_like(x)\nlolims[[6]] = True  # only limited at this index\nuplims[[3]] = True  # only limited at this index\n\n# do the plotting\nax.errorbar(x, y + 2.1, xerr=xerr, yerr=yerr,\n            xlolims=xlolims, xuplims=xuplims,\n            uplims=uplims, lolims=lolims,\n            marker='o', markersize=8, linestyle='none')"}]},{"title":"Display Plot","body":["Finally, we will display the plot using the show function."],"code":[{"lang":"python","text":"# tidy up the figure\nax.set_xlim((0, 5.5))\nax.set_title('Errorbar upper and lower limits')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# tidy up the figure\nax.set_xlim((0, 5.5))\nax.set_title('Errorbar upper and lower limits')\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-errorbar-limit-selection":{"intro":"In data visualization, it is often necessary to show the degree of uncertainty in the data being plotted. Error bars are a convenient way to represent this uncertainty. In this lab, we will learn how to selectively draw lower and/or upper limit symbols on error bars using the parameters uplims and lolims in Matplotlib.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","In this step, we import the necessary libraries to create our plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create the data","body":["In this step, we create the data that we will use to create our error bar plot."],"code":[{"lang":"python","text":"x = np.arange(10)\ny = 2.5 * np.sin(x / 20 * np.pi)\nyerr = np.linspace(0.05, 0.2, 10)"}]},{"title":"Create the error bar plot with both limits (default)","body":["Create the error bar plot with both limits (default)","In this step, we create an error bar plot with both upper and lower limits, which is the default behavior."],"code":[{"lang":"python","text":"plt.errorbar(x, y + 3, yerr=yerr, label='both limits (default)')"}]},{"title":"Create the error bar plot with upper limits only","body":["Create the error bar plot with upper limits only","In this step, we create an error bar plot with only upper limits."],"code":[{"lang":"python","text":"plt.errorbar(x, y + 2, yerr=yerr, uplims=True, label='uplims=True')"}]},{"title":"Create the error bar plot with both upper and lower limits","body":["Create the error bar plot with both upper and lower limits","In this step, we create an error bar plot with both upper and lower limits."],"code":[{"lang":"python","text":"plt.errorbar(x, y + 1, yerr=yerr, uplims=True, lolims=True, label='uplims=True, lolims=True')"}]},{"title":"Create the error bar plot with subsets of upper and lower limits","body":["Create the error bar plot with subsets of upper and lower limits","In this step, we create an error bar plot with subsets of upper and lower limits."],"code":[{"lang":"python","text":"upperlimits = [True, False] * 5\nlowerlimits = [False, True] * 5\nplt.errorbar(x, y, yerr=yerr, uplims=upperlimits, lolims=lowerlimits, label='subsets of uplims and lolims')"}]},{"title":"Create the error bar plot with horizontal error bars","body":["Create the error bar plot with horizontal error bars","In this step, we create an error bar plot with horizontal error bars."],"code":[{"lang":"python","text":"x = np.arange(10) / 10\ny = (x + 0.1)**2\n\nplt.errorbar(x, y, xerr=0.1, xlolims=True, label='xlolims=True')\ny = (x + 0.1)**3\n\nplt.errorbar(x + 0.6, y, xerr=0.1, xuplims=upperlimits, xlolims=lowerlimits, label='subsets of xuplims and xlolims')\n\ny = (x + 0.1)**4\nplt.errorbar(x + 1.2, y, xerr=0.1, xuplims=True, label='xuplims=True')"}]},{"title":"Add a legend and show the plot","body":["Add a legend and show the plot","In this step, we add a legend to the plot and display it."],"code":[{"lang":"python","text":"plt.legend(loc='lower right')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.legend(loc='lower right')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-errorbar-subsampling-with-matplotlib":{"intro":"In data visualization, it is sometimes useful to plot error bars to show the uncertainty or variability of the data. However, if there are many data points with similar errors, the plot can become cluttered and difficult to interpret. In such cases, we can use errorbar subsampling, which allows us to draw error bars only on a subset of data points. In this tutorial, we will use Matplotlib's errorbar function to demonstrate how to apply errorbar subsampling to our data.","steps":[{"title":"Import Libraries and Generate Data","body":["Import Libraries and Generate Data","First, we need to import the necessary libraries and generate some example data to work with. In this example, we will use numpy to generate the data and matplotlib to visualize it."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# example data\nx = np.arange(0.1, 4, 0.1)\ny1 = np.exp(-1.0 * x)\ny2 = np.exp(-0.5 * x)\n\n# example variable error bar values\ny1err = 0.1 + 0.1 * np.sqrt(x)\ny2err = 0.1 + 0.1 * np.sqrt(x/2)"}]},{"title":"Plot All Errorbars","body":["Next, we will plot all the error bars using the errorbar function without any subsampling. This will serve as our baseline plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nax.set_title('All Errorbars')\nax.errorbar(x, y1, yerr=y1err, label='y1')\nax.errorbar(x, y2, yerr=y2err, label='y2')\n\nax.legend()\nplt.show()"}]},{"title":"Subsample Every 6th Errorbar","body":["Now, let's apply errorbar subsampling to plot only every 6th error bar. We can do this by using the errorevery parameter of the errorbar function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nax.set_title('Every 6th Errorbar')\nax.errorbar(x, y1, yerr=y1err, errorevery=6, label='y1')\nax.errorbar(x, y2, yerr=y2err, errorevery=6, label='y2')\n\nax.legend()\nplt.show()"}]},{"title":"Shift Second Series by 3","body":["In some cases, we may want to apply errorbar subsampling to different parts of our data. We can do this by specifying a tuple for the errorevery parameter. For example, let's apply errorbar subsampling to the second series, but shift it by 3 data points."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nax.set_title('Second Series Shifted by 3')\nax.errorbar(x, y1, yerr=y1err, label='y1')\nax.errorbar(x, y2, yerr=y2err, errorevery=(3, 6), label='y2')\n\nax.legend()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\n\nax.set_title('Second Series Shifted by 3')\nax.errorbar(x, y1, yerr=y1err, label='y1')\nax.errorbar(x, y2, yerr=y2err, errorevery=(3, 6), label='y2')\n\nax.legend()\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-3d-plots-with-error-bars-in-python":{"intro":"In this tutorial, we will learn how to create a 3D plot with error bars using Python's Matplotlib library. Error bars are a graphical representation of the variability of data and are often used in scientific and engineering fields to show uncertainties in measurements or statistical estimates.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries, which are Matplotlib and NumPy. NumPy is a numerical computing library that provides support for arrays and matrices, while Matplotlib is a data visualization library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a 3D Plot","body":["Next, we create a 3D plot by using the add_subplot method of the figure object. We set the projection parameter to '3d' to specify that we want a 3D plot."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')"}]},{"title":"Generate Data for the Plot","body":["We generate the data for our plot by creating a parametric curve. A parametric curve is a set of equations that describe the x, y, and z coordinates as a function of a parameter. We use NumPy's arange function to create an array of values from 0 to 2π. We then use these values to calculate the x, y, and z coordinates using trigonometric functions."],"code":[{"lang":"python","text":"t = np.arange(0, 2*np.pi+.1, 0.01)\nx, y, z = np.sin(t), np.cos(3*t), np.sin(5*t)"}]},{"title":"Add Error Bars to the Plot","body":["We add error bars to our plot using the errorbar method of the Axes3D object. We set the zuplims and zlolims parameters to arrays that specify which data points have upper and lower limits. We set the errorevery parameter to control the frequency of error bars."],"code":[{"lang":"python","text":"estep = 15\ni = np.arange(t.size)\nzuplims = (i % estep == 0) & (i // estep % 3 == 0)\nzlolims = (i % estep == 0) & (i // estep % 3 == 2)\n\nax.errorbar(x, y, z, 0.2, zuplims=zuplims, zlolims=zlolims, errorevery=estep)"}]},{"title":"Customize the Plot","body":["We can customize our plot by adding labels to the x, y, and z axes using the set_xlabel, set_ylabel, and set_zlabel methods."],"code":[{"lang":"python","text":"ax.set_xlabel(\"X label\")\nax.set_ylabel(\"Y label\")\nax.set_zlabel(\"Z label\")"}]},{"title":"Display the Plot","body":["Finally, we use the show method to display our plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-boxes-from-error-bars-using-patchco":{"intro":"In this lab, we will learn how to create box plots from error bars using PatchCollection. Box plots are useful for displaying the range and distribution of data. By adding a rectangle patch defined by the limits of the bars in both the x- and y-directions, we can make a more visually appealing error bar plot.","steps":[{"title":"Import Libraries","body":["We will first import the necessary libraries, including numpy and matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.collections import PatchCollection\nfrom matplotlib.patches import Rectangle"}]},{"title":"Prepare Data","body":["We will then prepare the data for our box plot. We will create some dummy data for the x and y values, as well as the error values."],"code":[{"lang":"python","text":"# Number of data points\nn = 5\n\n# Dummy data\nnp.random.seed(19680801)\nx = np.arange(0, n, 1)\ny = np.random.rand(n) * 5.\n\n# Dummy errors (above and below)\nxerr = np.random.rand(2, n) + 0.1\nyerr = np.random.rand(2, n) + 0.2"}]},{"title":"Create Function for Error Boxes","body":["Create Function for Error Boxes","We will now create a function called make_error_boxes that will create the rectangle patch defined by the limits of the bars in both the x- and y-directions."],"code":[{"lang":"python","text":"def make_error_boxes(ax, xdata, ydata, xerror, yerror, facecolor='r',\n                     edgecolor='none', alpha=0.5):\n\n    # Loop over data points; create box from errors at each point\n    errorboxes = [Rectangle((x - xe[0], y - ye[0]), xe.sum(), ye.sum())\n                  for x, y, xe, ye in zip(xdata, ydata, xerror.T, yerror.T)]\n\n    # Create patch collection with specified colour/alpha\n    pc = PatchCollection(errorboxes, facecolor=facecolor, alpha=alpha,\n                         edgecolor=edgecolor)\n\n    # Add collection to axes\n    ax.add_collection(pc)\n\n    # Plot errorbars\n    artists = ax.errorbar(xdata, ydata, xerr=xerror, yerr=yerror,\n                          fmt='none', ecolor='k')\n\n    return artists"}]},{"title":"Create Figure and Axes","body":["We will now create the figure and axes for our box plot using plt.subplots()."],"code":[{"lang":"python","text":"# Create figure and axes\nfig, ax = plt.subplots(1)"}]},{"title":"Call Function to Create Error Boxes","body":["Call Function to Create Error Boxes","We will now call the make_error_boxes() function to create the error boxes on our plot."],"code":[{"lang":"python","text":"# Call function to create error boxes\n_ = make_error_boxes(ax, x, y, xerr, yerr)"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-custom-units":{"intro":"Matplotlib is a plotting library for the Python programming language. It provides an object-oriented API for embedding plots into applications using general-purpose GUI toolkits like Tkinter, wxPython, Qt, or GTK. Matplotlib allows developers to create a wide range of static, animated, and interactive visualizations in Python.","steps":[{"title":"Import Libraries","body":["In the first step, we need to import the required libraries - matplotlib.pyplot, numpy, matplotlib.ticker, and matplotlib.units."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.ticker as ticker\nimport matplotlib.units as units"}]},{"title":"Create a Custom Unit Class","body":["In this step, we will create a custom unit class - Foo. This class will support conversion and different tick formatting depending on the \"unit\". Here, the \"unit\" is just a scalar conversion factor."],"code":[{"lang":"python","text":"class Foo:\n    def __init__(self, val, unit=1.0):\n        self.unit = unit\n        self._val = val * unit\n\n    def value(self, unit):\n        if unit is None:\n            unit = self.unit\n        return self._val / unit"}]},{"title":"Create a Converter Class","body":["In this step, we will create a converter class - FooConverter. This class will define three static methods - axisinfo, convert, and default_units."],"code":[{"lang":"python","text":"class FooConverter(units.ConversionInterface):\n    @staticmethod\n    def axisinfo(unit, axis):\n        \"\"\"Return the Foo AxisInfo.\"\"\"\n        if unit == 1.0 or unit == 2.0:\n            return units.AxisInfo(\n                majloc=ticker.IndexLocator(8, 0),\n                majfmt=ticker.FormatStrFormatter(\"VAL: %s\"),\n                label='foo',\n                )\n\n        else:\n            return None\n\n    @staticmethod\n    def convert(obj, unit, axis):\n        \"\"\"\n        Convert *obj* using *unit*.\n\n        If *obj* is a sequence, return the converted sequence.\n        \"\"\"\n        if np.iterable(obj):\n            return [o.value(unit) for o in obj]\n        else:\n            return obj.value(unit)\n\n    @staticmethod\n    def default_units(x, axis):\n        \"\"\"Return the default unit for *x* or None.\"\"\"\n        if np.iterable(x):\n            for thisx in x:\n                return thisx.unit\n        else:\n            return x.unit"}]},{"title":"Register the Custom Unit Class","body":["Register the Custom Unit Class","In this step, we will register the custom unit class - Foo - with the converter class - FooConverter."],"code":[{"lang":"python","text":"units.registry[Foo] = FooConverter()"}]},{"title":"Create Data Points","body":["In this step, we will create some data points using the custom unit class - Foo."],"code":[{"lang":"python","text":"# create some Foos\nx = [Foo(val, 1.0) for val in range(0, 50, 2)]\n# and some arbitrary y data\ny = [i for i in range(len(x))]"}]},{"title":"Create Plots","body":["In this step, we will create two plots - one using custom units and the other using default units."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2)\nfig.suptitle(\"Custom units\")\nfig.subplots_adjust(bottom=0.2)\n\n# plot specifying units\nax2.plot(x, y, 'o', xunits=2.0)\nax2.set_title(\"xunits = 2.0\")\nplt.setp(ax2.get_xticklabels(), rotation=30, ha='right')\n\n# plot without specifying units; will use the None branch for axisinfo\nax1.plot(x, y)  # uses default units\nax1.set_title('default units')\nplt.setp(ax1.get_xticklabels(), rotation=30, ha='right')\n\nplt.show()"}]},{"title":"Run the Code","body":["In the final step, run the code to create the custom unit plots."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-line-plot-with-data-points":{"intro":"In this lab, we will learn how to create a line plot with data points using Matplotlib in Python. We will use the EventCollection class in Matplotlib to mark the locations of the x and y data points on the respective axes for each curve.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the required libraries. We will use numpy to create random data, matplotlib.pyplot to create the plot, and EventCollection from matplotlib.collections to mark the locations of data points."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.collections import EventCollection"}]},{"title":"Create random data","body":["We will create random data for two curves using numpy.random.random() function. We will generate two sets of 10 random numbers between 0 and 1 and store them in an array."],"code":[{"lang":"python","text":"# create random data\nxdata = np.random.random([2, 10])"}]},{"title":"Sort the data","body":["To make clean curves, we will sort the data using the sort() method."],"code":[{"lang":"python","text":"# split the data into two parts\nxdata1 = xdata[0, :]\nxdata2 = xdata[1, :]\n# sort the data so it makes clean curves\nxdata1.sort()\nxdata2.sort()"}]},{"title":"Create y data points","body":["We will create some y data points for each curve by performing some mathematical operations on the sorted x data points."],"code":[{"lang":"python","text":"# create some y data points\nydata1 = xdata1 ** 2\nydata2 = 1 - xdata2 ** 3"}]},{"title":"Create the plot","body":["We will create the plot using matplotlib.pyplot.plot() function."],"code":[{"lang":"python","text":"# plot the data\nfig = plt.figure()\nax = fig.add_subplot(1, 1, 1)\nax.plot(xdata1, ydata1, color='tab:blue')\nax.plot(xdata2, ydata2, color='tab:orange')"}]},{"title":"Create the events","body":["We will create the events marking the x and y data points using EventCollection() function."],"code":[{"lang":"python","text":"# create the events marking the x data points\nxevents1 = EventCollection(xdata1, color='tab:blue', linelength=0.05)\nxevents2 = EventCollection(xdata2, color='tab:orange', linelength=0.05)\n\n# create the events marking the y data points\nyevents1 = EventCollection(ydata1, color='tab:blue', linelength=0.05,\n                           orientation='vertical')\nyevents2 = EventCollection(ydata2, color='tab:orange', linelength=0.05,\n                           orientation='vertical')"}]},{"title":"Add the events to the plot","body":["We will add the events to the plot using matplotlib.pyplot.add_collection() function."],"code":[{"lang":"python","text":"# add the events to the axis\nax.add_collection(xevents1)\nax.add_collection(xevents2)\nax.add_collection(yevents1)\nax.add_collection(yevents2)"}]},{"title":"Set the limits and add title","body":["We will set the limits of the x and y axes and add a title to the plot using matplotlib.pyplot.xlim(), matplotlib.pyplot.ylim(), and matplotlib.pyplot.title() functions."],"code":[{"lang":"python","text":"# set the limits\nax.set_xlim([0, 1])\nax.set_ylim([0, 1])\nax.set_title('line plot with data points')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# display the plot\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-event-plots-with-matplotlib":{"intro":"In this lab, you will learn how to create an event plot using Matplotlib. An event plot is a way to show the occurrence of events over time. The events can be represented as lines or dots. This lab will guide you through creating horizontal and vertical event plots with different line properties.","steps":[{"title":"Import libraries and set random seed","body":["Import libraries and set random seed","We will start by importing the necessary libraries and setting a random seed for reproducibility."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nimport matplotlib\n\nmatplotlib.rcParams['font.size'] = 8.0\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)"}]},{"title":"Create random data","body":["Next, we will create some random data to use for our event plots."],"code":[{"lang":"python","text":"data1 = np.random.random([6, 50])"}]},{"title":"Set colors and line properties for the first event plot","body":["Set colors and line properties for the first event plot","We will set different colors and line properties for each set of positions in the first event plot."],"code":[{"lang":"python","text":"colors1 = [f'C{i}' for i in range(6)]\n\nlineoffsets1 = [-15, -3, 1, 1.5, 6, 10]\nlinelengths1 = [5, 2, 1, 1, 3, 1.5]"}]},{"title":"Create the first event plot - horizontal orientation","body":["Create the first event plot - horizontal orientation","We will create the first event plot in a horizontal orientation."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 2)\n\naxs[0, 0].eventplot(data1, colors=colors1, lineoffsets=lineoffsets1,\n                    linelengths=linelengths1)"}]},{"title":"Create the first event plot - vertical orientation","body":["Create the first event plot - vertical orientation","We will create the first event plot in a vertical orientation."],"code":[{"lang":"python","text":"axs[1, 0].eventplot(data1, colors=colors1, lineoffsets=lineoffsets1,\n                    linelengths=linelengths1, orientation='vertical')"}]},{"title":"Create random data for the second event plot","body":["Create random data for the second event plot","We will create another set of random data for the second event plot. We will use the gamma distribution for aesthetic purposes."],"code":[{"lang":"python","text":"data2 = np.random.gamma(4, size=[60, 50])"}]},{"title":"Set line properties for the second event plot","body":["Set line properties for the second event plot","We will use individual values for the line properties in the second event plot. These values will be used for all data sets except for lineoffsets2, which sets the increment between each data set."],"code":[{"lang":"python","text":"colors2 = 'black'\nlineoffsets2 = 1\nlinelengths2 = 1"}]},{"title":"Create the second event plot - horizontal orientation","body":["Create the second event plot - horizontal orientation","We will create the second event plot in a horizontal orientation."],"code":[{"lang":"python","text":"axs[0, 1].eventplot(data2, colors=colors2, lineoffsets=lineoffsets2,\n                    linelengths=linelengths2)"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-fahrenheit-celsius-scales":{"intro":"The purpose of this lab is to demonstrate how to display two scales on the left and right y-axis. This example uses the Fahrenheit and Celsius scales. We will use a closure function to register as a callback to update the second axis according to the first axis.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the numpy and matplotlib.pyplot libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define a function to convert Fahrenheit to Celsius","body":["Define a function to convert Fahrenheit to Celsius","Next, we define a function to convert temperature in Fahrenheit to Celsius."],"code":[{"lang":"python","text":"def fahrenheit2celsius(temp):\n    \"\"\"\n    Returns temperature in Celsius given Fahrenheit temperature.\n    \"\"\"\n    return (5. / 9.) * (temp - 32)"}]},{"title":"Define a function to update the second axis","body":["Define a function to update the second axis","We will define a closure function to register as a callback to update the second axis according to the first axis."],"code":[{"lang":"python","text":"def convert_ax_c_to_celsius(ax_f):\n    \"\"\"\n    Update second axis according to first axis.\n    \"\"\"\n    y1, y2 = ax_f.get_ylim()\n    ax_c.set_ylim(fahrenheit2celsius(y1), fahrenheit2celsius(y2))\n    ax_c.figure.canvas.draw()"}]},{"title":"Create the plot","body":["Now, we create a plot with two y-axes using the subplots() function of matplotlib.pyplot. We also connect the ylim_changed event of the first axis to the convert_ax_c_to_celsius() function."],"code":[{"lang":"python","text":"fig, ax_f = plt.subplots()\nax_c = ax_f.twinx()\n\nax_f.callbacks.connect(\"ylim_changed\", convert_ax_c_to_celsius)"}]},{"title":"Plot the data","body":["We plot the data using the plot() function of the first axis."],"code":[{"lang":"python","text":"ax_f.plot(np.linspace(-40, 120, 100))"}]},{"title":"Set the axis limits and labels","body":["Set the axis limits and labels","We set the x-axis limits to (0,100), and the y-axis labels and title."],"code":[{"lang":"python","text":"ax_f.set_xlim(0, 100)\nax_f.set_title('Two scales: Fahrenheit and Celsius')\nax_f.set_ylabel('Fahrenheit')\nax_c.set_ylabel('Celsius')"}]},{"title":"Display the plot","body":["Finally, we display the plot using the show() function of matplotlib.pyplot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-matplotlib-arrow-reference-chart":{"intro":"This tutorial will walk you through the process of creating an arrow style reference chart using Matplotlib in Python. The chart will display the different arrow styles available in ~.Axes.annotate.","steps":[{"title":"Import Necessary Libraries","body":["Import the necessary libraries to create the arrow style reference chart."],"code":[{"lang":"python","text":"import inspect\nimport itertools\nimport re\n\nimport matplotlib.pyplot as plt\n\nimport matplotlib.patches as mpatches"}]},{"title":"Get Arrow Styles","body":["Use mpatches.ArrowStyle.get_styles() to get all the arrow styles available in ~.Axes.annotate."],"code":[{"lang":"python","text":"styles = mpatches.ArrowStyle.get_styles()"}]},{"title":"Set Up Figure","body":["Set up the figure using plt.figure() and add_gridspec(). The figure will have a grid of 2 columns and n rows, where n is the number of arrow styles. Each cell in the grid will contain an arrow style and its default parameters."],"code":[{"lang":"python","text":"ncol = 2\nnrow = (len(styles) + 1) // ncol\naxs = (plt.figure(figsize=(4 * ncol, 1 + nrow))\n       .add_gridspec(1 + nrow, ncol,\n                     wspace=.7, left=.1, right=.9, bottom=0, top=1).subplots())\nfor ax in axs.flat:\n    ax.set_axis_off()\nfor ax in axs[0, :]:\n    ax.text(0, .5, \"arrowstyle\",\n            transform=ax.transAxes, size=\"large\", color=\"tab:blue\",\n            horizontalalignment=\"center\", verticalalignment=\"center\")\n    ax.text(.35, .5, \"default parameters\",\n            transform=ax.transAxes,\n            horizontalalignment=\"left\", verticalalignment=\"center\")"}]},{"title":"Plot Arrow Styles","body":["Plot each arrow style in a cell of the grid, along with its default parameters. Use ax.annotate() to add the arrow style name and its default parameters to the cell."],"code":[{"lang":"python","text":"for ax, (stylename, stylecls) in zip(axs[1:, :].T.flat, styles.items()):\n    l, = ax.plot(.25, .5, \"ok\", transform=ax.transAxes)\n    ax.annotate(stylename, (.25, .5), (-0.1, .5),\n                xycoords=\"axes fraction\", textcoords=\"axes fraction\",\n                size=\"large\", color=\"tab:blue\",\n                horizontalalignment=\"center\", verticalalignment=\"center\",\n                arrowprops=dict(\n                    arrowstyle=stylename, connectionstyle=\"arc3,rad=-0.05\",\n                    color=\"k\", shrinkA=5, shrinkB=5, patchB=l,\n                ),\n                bbox=dict(boxstyle=\"square\", fc=\"w\"))\n    # wrap at every nth comma (n = 1 or 2, depending on text length)\n    s = str(inspect.signature(stylecls))[1:-1]\n    n = 2 if s.count(',') > 3 else 1\n    ax.text(.35, .5,\n            re.sub(', ', lambda m, c=itertools.count(1): m.group()\n                   if next(c) % n else '\\n', s),\n            transform=ax.transAxes,\n            horizontalalignment=\"left\", verticalalignment=\"center\")"}]},{"title":"Display Chart","body":["Display the arrow style reference chart using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-drawing-fancy-boxes-with-matplotlib":{"intro":"Matplotlib is a popular data visualization library in Python. This lab will guide you through the process of creating fancy boxes with different visual properties.","steps":[{"title":"Import libraries and get box styles","body":["Import libraries and get box styles","In this step, we will import the necessary libraries and get the box styles that we will use for plotting."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.patches as mpatch\nfrom matplotlib.patches import FancyBboxPatch\nimport matplotlib.transforms as mtransforms\nimport inspect\n\nstyles = mpatch.BoxStyle.get_styles()"}]},{"title":"Plot sample boxes with fancybox","body":["Plot sample boxes with fancybox","In this step, we will plot sample boxes with fancybox using the box styles that we got in step 1."],"code":[{"lang":"python","text":"ncol = 2\nnrow = (len(styles) + 1) // ncol\naxs = (plt.figure(figsize=(3 * ncol, 1 + nrow))\n       .add_gridspec(1 + nrow, ncol, wspace=.5).subplots())\n\nfor ax in axs.flat:\n    ax.set_axis_off()\n\nfor ax in axs[0, :]:\n    ax.text(.2, .5, \"boxstyle\",\n            transform=ax.transAxes, size=\"large\", color=\"tab:blue\",\n            horizontalalignment=\"right\", verticalalignment=\"center\")\n    ax.text(.4, .5, \"default parameters\",\n            transform=ax.transAxes,\n            horizontalalignment=\"left\", verticalalignment=\"center\")\n\nfor ax, (stylename, stylecls) in zip(axs[1:, :].T.flat, styles.items()):\n    ax.text(.2, .5, stylename, bbox=dict(boxstyle=stylename, fc=\"w\", ec=\"k\"),\n            transform=ax.transAxes, size=\"large\", color=\"tab:blue\",\n            horizontalalignment=\"right\", verticalalignment=\"center\")\n    ax.text(.4, .5, str(inspect.signature(stylecls))[1:-1].replace(\", \", \"\\n\"),\n            transform=ax.transAxes,\n            horizontalalignment=\"left\", verticalalignment=\"center\")"}]},{"title":"Show multiple fancy boxes at once","body":["Show multiple fancy boxes at once","In this step, we will show multiple fancy boxes at once with different visual properties."],"code":[{"lang":"python","text":"def add_fancy_patch_around(ax, bb, **kwargs):\n    fancy = FancyBboxPatch(bb.p0, bb.width, bb.height,\n                           fc=(1, 0.8, 1, 0.5), ec=(1, 0.5, 1, 0.5),\n                           **kwargs)\n    ax.add_patch(fancy)\n    return fancy\n\n\ndef draw_control_points_for_patches(ax):\n    for patch in ax.patches:\n        patch.axes.plot(*patch.get_path().vertices.T, \".\",\n                        c=patch.get_edgecolor())\n\n\nfig, axs = plt.subplots(2, 2, figsize=(8, 8))\n\nbb = mtransforms.Bbox([[0.3, 0.4], [0.7, 0.6]])\n\nax = axs[0, 0]\nfancy = add_fancy_patch_around(ax, bb, boxstyle=\"round,pad=0.1\")\nax.set(xlim=(0, 1), ylim=(0, 1), aspect=1,\n       title='boxstyle=\"round,pad=0.1\"')\n\nax = axs[0, 1]\nfancy = add_fancy_patch_around(ax, bb, boxstyle=\"round,pad=0.1\")\nfancy.set_boxstyle(\"round,pad=0.1,rounding_size=0.2\")\nax.set(xlim=(0, 1), ylim=(0, 1), aspect=1,\n       title='boxstyle=\"round,pad=0.1,rounding_size=0.2\"')\n\nax = axs[1, 0]\nfancy = add_fancy_patch_around(\n    ax, bb, boxstyle=\"round,pad=0.1\", mutation_scale=2)\nax.set(xlim=(0, 1), ylim=(0, 1), aspect=1,\n       title='boxstyle=\"round,pad=0.1\"\\n mutation_scale=2')\n\nax = axs[1, 1]\nfancy = add_fancy_patch_around(ax, bb, boxstyle=\"round,pad=0.2\")\nfancy.set(facecolor=\"none\", edgecolor=\"green\")\nfancy = add_fancy_patch_around(\n    ax, bb, boxstyle=\"round,pad=0.3\", mutation_aspect=0.5)\nax.set(xlim=(-.5, 1.5), ylim=(0, 1), aspect=2,\n       title='boxstyle=\"round,pad=0.3\"\\nmutation_aspect=.5')\n\nfor ax in axs.flat:\n    draw_control_points_for_patches(ax)\n    fancy = add_fancy_patch_around(ax, bb, boxstyle=\"square,pad=0\")\n    fancy.set(edgecolor=\"black\", facecolor=\"none\", zorder=10)"}]},{"title":"Conclusion","body":["In this lab, we learned how to create fancy boxes with different visual properties using Matplotlib."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-styling-text-boxes-using-bbox-parameters":{"intro":"In data visualization, it is important to highlight specific information to draw the viewer's attention. One way to do this is by styling text boxes using bbox parameters in Matplotlib. In this lab, we will learn how to style text boxes using bbox parameters in Matplotlib.","steps":[{"title":"Import Required Libraries","body":[],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a Text Box","body":["We create a text box containing the word \"eggs\" using the text() method. The bbox parameter is used to style the box. The boxstyle parameter is set to \"round\" to create a rounded box, while ec and fc parameters set the edge and face colors of the box, respectively. The size parameter sets the font size, rotation parameter sets the rotation angle, and ha and va parameters set the horizontal and vertical alignment of the text in the box."],"code":[{"lang":"python","text":"plt.text(0.6, 0.7, \"eggs\", size=50, rotation=30.,\n         ha=\"center\", va=\"center\",\n         bbox=dict(boxstyle=\"round\",\n                   ec=(1., 0.5, 0.5),\n                   fc=(1., 0.8, 0.8),\n                   )\n         )"}]},{"title":"Create Another Text Box","body":["We create another text box containing the word \"spam\". This time we set boxstyle parameter to \"square\" to create a square box and set ha and va parameters to \"right\" and \"top\" to align the text to the right and top of the box."],"code":[{"lang":"python","text":"plt.text(0.55, 0.6, \"spam\", size=50, rotation=-25.,\n         ha=\"right\", va=\"top\",\n         bbox=dict(boxstyle=\"square\",\n                   ec=(1., 0.5, 0.5),\n                   fc=(1., 0.8, 0.8),\n                   )\n         )"}]},{"title":"Display the Plot","body":["Finally, we display the plot by calling the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-customizing-plot-axes":{"intro":"In this tutorial, we will learn how to customize the background, labels, and ticks of a simple plot using Matplotlib.","steps":[{"title":"Importing necessary libraries","body":["We will start by importing the necessary libraries that we will use in this tutorial."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Creating a figure and setting the background","body":["Creating a figure and setting the background","We will create a figure using the plt.figure() method, which creates a matplotlib.figure.Figure instance. We will set the background color of the figure using the rect.set_facecolor() method."],"code":[{"lang":"python","text":"fig = plt.figure()\nrect = fig.patch  # a rectangle instance\nrect.set_facecolor('lightgoldenrodyellow')"}]},{"title":"Adding axes to the figure","body":["We will add axes to the figure using the fig.add_axes() method. We will also set the background color of the axes using the rect.set_facecolor() method."],"code":[{"lang":"python","text":"ax1 = fig.add_axes([0.1, 0.3, 0.4, 0.4])\nrect = ax1.patch\nrect.set_facecolor('lightslategray')"}]},{"title":"Customizing the ticks and labels","body":["Customizing the ticks and labels","We will customize the ticks and labels of the axes using the ax1.tick_params() method. We will set the color, rotation, and size of the x-axis label, and the color, size, and width of the y-axis ticks."],"code":[{"lang":"python","text":"ax1.tick_params(axis='x', labelcolor='tab:red', labelrotation=45, labelsize=16)\nax1.tick_params(axis='y', color='tab:green', size=25, width=3)"}]},{"title":"Displaying the plot","body":["Finally, we will display the plot using the plt.show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-adding-lines-to-figures":{"intro":"In this lab, we will learn how to add lines to a figure without any axes using Matplotlib in Python.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries. We will be using matplotlib.pyplot and matplotlib.lines for this lab."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.lines as lines"}]},{"title":"Create a Figure object","body":["Next, we create a Figure object using the plt.figure() method."],"code":[{"lang":"python","text":"fig = plt.figure()"}]},{"title":"Add lines to the Figure","body":["We can add lines to the figure using the fig.add_artist() method. We will create two lines - one from (0,0) to (1,1) and another from (0,1) to (1,0)."],"code":[{"lang":"python","text":"fig.add_artist(lines.Line2D([0, 1], [0, 1]))\nfig.add_artist(lines.Line2D([0, 1], [1, 0]))"}]},{"title":"Display the Figure","body":["Finally, we display the figure using the plt.show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-figure-image":{"intro":"In this lab, you will learn how to use Matplotlib's figimage function to place images directly in a figure, without the need for Axes objects. This can be useful when you want to include images that are not part of your plot, such as a logo or watermark.","steps":[{"title":"Importing the necessary libraries","body":["Importing the necessary libraries","First, we need to import the necessary libraries, which are matplotlib.pyplot and numpy. We will use numpy to create an array of random values that we will use as our image."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating the figure and image","body":["Next, we create the figure and the image that we want to place in it. In this example, we create a 100x100 array of random values and set the values in the right half of the image to 1. We then create two separate instances of the image, each with a different position and opacity."],"code":[{"lang":"python","text":"fig = plt.figure()\nZ = np.arange(10000).reshape((100, 100))\nZ[:, 50:] = 1\n\nim1 = fig.figimage(Z, xo=50, yo=0, origin='lower')\nim2 = fig.figimage(Z, xo=100, yo=100, alpha=.8, origin='lower')"}]},{"title":"Showing the figure","body":["Finally, we display the figure with the images using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-matplotlib-legends-for-data-visuali":{"intro":"In data visualization, legends help the viewer understand what they are looking at. Legends in Matplotlib are labels that describe the elements of a graph. This tutorial will show how to create legends for a Matplotlib figure.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries - NumPy and Matplotlib. NumPy is a Python library that is used for working with arrays, while Matplotlib is a data visualization library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating a Basic Plot","body":["To create a basic plot, we need to define the x and y values and then plot them using plt.plot(). Here, we will plot two sine waves."],"code":[{"lang":"python","text":"x = np.arange(0.0, 2.0, 0.02)\ny1 = np.sin(2 * np.pi * x)\ny2 = np.sin(4 * np.pi * x)\n\nplt.plot(x, y1, label='sin(2pix)')\nplt.plot(x, y2, label='sin(4pix)')"}]},{"title":"Adding a Legend","body":["To add a legend to the plot, we use the plt.legend() function. We can pass the labels for each line as a list of strings to the labels parameter of the function."],"code":[{"lang":"python","text":"plt.legend(labels=['sin(2pix)', 'sin(4pix)'])"}]},{"title":"Customizing the Legend","body":["We can customize the legend by changing its position, font size, and other parameters. To change the position of the legend, we use the loc parameter. We can also change the font size using the fontsize parameter."],"code":[{"lang":"python","text":"plt.legend(labels=['sin(2pix)', 'sin(4pix)'], loc='lower right', fontsize='large')"}]},{"title":"Creating a Legend for Subplots","body":["Creating a Legend for Subplots","When creating subplots, we can create a legend for all the subplots by using the fig.legend() function. Here, we will create two subplots and plot two lines on each subplot."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(1, 2)\n\nx = np.arange(0.0, 2.0, 0.02)\ny1 = np.sin(2 * np.pi * x)\ny2 = np.exp(-x)\nl1, = axs[0].plot(x, y1)\nl2, = axs[0].plot(x, y2, marker='o')\n\ny3 = np.sin(4 * np.pi * x)\ny4 = np.exp(-2 * x)\nl3, = axs[1].plot(x, y3, color='tab:green')\nl4, = axs[1].plot(x, y4, color='tab:red', marker='^')\n\nfig.legend((l1, l2), ('Line 1', 'Line 2'), loc='upper left')\nfig.legend((l3, l4), ('Line 3', 'Line 4'), loc='upper right')"}]},{"title":"Placing the Legend Outside the Axes","body":["Placing the Legend Outside the Axes","Sometimes, we may want the legend to be outside the axes. We can use the loc parameter to specify the location of the legend outside the axes."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(1, 2, layout='constrained')\n\nx = np.arange(0.0, 2.0, 0.02)\ny1 = np.sin(2 * np.pi * x)\ny2 = np.exp(-x)\nl1, = axs[0].plot(x, y1)\nl2, = axs[0].plot(x, y2, marker='o')\n\ny3 = np.sin(4 * np.pi * x)\ny4 = np.exp(-2 * x)\nl3, = axs[1].plot(x, y3, color='tab:green')\nl4, = axs[1].plot(x, y4, color='tab:red', marker='^')\n\nfig.legend((l1, l2), ('Line 1', 'Line 2'), loc='upper left')\nfig.legend((l3, l4), ('Line 3', 'Line 4'), loc='outside right upper')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, axs = plt.subplots(1, 2, layout='constrained')\n\nx = np.arange(0.0, 2.0, 0.02)\ny1 = np.sin(2 * np.pi * x)\ny2 = np.exp(-x)\nl1, = axs[0].plot(x, y1)\nl2, = axs[0].plot(x, y2, marker='o')\n\ny3 = np.sin(4 * np.pi * x)\ny4 = np.exp(-2 * x)\nl3, = axs[1].plot(x, y3, color='tab:green')\nl4, = axs[1].plot(x, y4, color='tab:red', marker='^')\n\nfig.legend((l1, l2), ('Line 1', 'Line 2'), loc='upper left')\nfig.legend((l3, l4), ('Line 3', 'Line 4'), loc='outside right upper')"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-figure-and-axes-enter-leave-event":{"intro":"Matplotlib is a data visualization library for Python. It offers a variety of tools for creating static, animated, and interactive visualizations in Python. One of the interactive features of Matplotlib is the ability to detect when the mouse enters and leaves a figure or an axes. In this lab, we will learn how to use Matplotlib's Figure and Axes enter/leave events to change the frame colors of the figure and axes.","steps":[{"title":"Importing Matplotlib","body":["Before we start using Matplotlib, we need to import it. We will also import the pyplot module, which provides a simple interface for creating plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Creating the Figure and Axes","body":["We will create a figure with two subplots (axes) using the subplots function. We will also set the title of the figure."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 1)\nfig.suptitle('Mouse Hover Over Figure or Axes to Trigger Events')"}]},{"title":"Defining the Event Handlers","body":["We will now define four event handler functions: on_enter_axes, on_leave_axes, on_enter_figure, and on_leave_figure. These functions will be called when the mouse enters or leaves an axes or the figure."],"code":[{"lang":"python","text":"def on_enter_axes(event):\n    print('enter_axes', event.inaxes)\n    event.inaxes.patch.set_facecolor('yellow')\n    event.canvas.draw()\n\ndef on_leave_axes(event):\n    print('leave_axes', event.inaxes)\n    event.inaxes.patch.set_facecolor('white')\n    event.canvas.draw()\n\ndef on_enter_figure(event):\n    print('enter_figure', event.canvas.figure)\n    event.canvas.figure.patch.set_facecolor('red')\n    event.canvas.draw()\n\ndef on_leave_figure(event):\n    print('leave_figure', event.canvas.figure)\n    event.canvas.figure.patch.set_facecolor('grey')\n    event.canvas.draw()"}]},{"title":"Connecting the Event Handlers to the Figure Canvas","body":["Connecting the Event Handlers to the Figure Canvas","We will now connect the event handlers to the figure canvas using the mpl_connect method. This will allow the event handlers to be triggered when the mouse enters or leaves the figure or axes."],"code":[{"lang":"python","text":"fig.canvas.mpl_connect('figure_enter_event', on_enter_figure)\nfig.canvas.mpl_connect('figure_leave_event', on_leave_figure)\nfig.canvas.mpl_connect('axes_enter_event', on_enter_axes)\nfig.canvas.mpl_connect('axes_leave_event', on_leave_axes)"}]},{"title":"Displaying the Figure","body":["We will now display the figure using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-figure-size-units":{"intro":"Matplotlib is a powerful data visualization library in Python. It is used to create high-quality graphs, charts, and figures for data analysis. In this lab, we will learn how to adjust figure size in different units using Matplotlib.","steps":[{"title":"Set Up Environment","body":["We also need to import Matplotlib in our code."],"code":[{"lang":"python","text":"!pip install matplotlib"},{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Figure Size in Inches (Default)","body":["Figure Size in Inches (Default)","The default figure size unit in Matplotlib is inches. We can specify the figure size using the figsize parameter in the subplots function. The code below shows how to create a figure with a size of 6 inches x 2 inches."],"code":[{"lang":"python","text":"plt.subplots(figsize=(6, 2))\nplt.show()"}]},{"title":"Figure Size in Centimeters","body":["We can also specify the figure size in centimeters. To do this, we need to convert the centimeter-based numbers to inches. We can do this by multiplying the centimeter value with the conversion factor from cm to inches, which is 1/2.54. We can then use this value as the figsize parameter in the subplots function. The code below shows how to create a figure with a size of 15 cm x 5 cm."],"code":[{"lang":"python","text":"cm = 1/2.54  # centimeters in inches\nplt.subplots(figsize=(15*cm, 5*cm))\nplt.show()"}]},{"title":"Figure Size in Pixel","body":["We can also specify the figure size in pixels. To do this, we need to convert the pixel value to inches. We can get the conversion factor from pixels to inches by dividing 1 by the dpi (dots per inch) value. We can then use this value as the figsize parameter in the subplots function. The code below shows how to create a figure with a size of 600 pixels x 200 pixels."],"code":[{"lang":"python","text":"px = 1/plt.rcParams['figure.dpi']  # pixel in inches\nplt.subplots(figsize=(600*px, 200*px))\nplt.show()"}]},{"title":"Quick Interactive Work","body":["For quick interactive work, pixels are usually a good size of unit. We can use the default dpi value of 100 to convert pixel values to inches. We can then use this value as the figsize parameter in the subplots function. The code below shows how to create a figure with a size of 6 inches x 2 inches using pixel values."],"code":[{"lang":"python","text":"plt.subplots(figsize=(600/100, 200/100))\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.subplots(figsize=(600/100, 200/100))\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-figures-with-matplotlib-in-python":{"intro":"This lab will guide you through the process of creating figures with titles, subtitles, and global labels using the Matplotlib library in Python. You will learn how to create different types of oscillation plots and how to add a global x- or y-label to a figure.","steps":[{"title":"Create a damped and undamped oscillation plot","body":["Create a damped and undamped oscillation plot","First, we will create a figure with two subplots, one for a damped oscillation and another for an undamped oscillation. We will use the np.linspace() function to create an array of time values and then plot the corresponding amplitude values for each type of oscillation using the np.cos() and np.exp() functions."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nx = np.linspace(0.0, 5.0, 501)\n\nfig, (ax1, ax2) = plt.subplots(1, 2, layout='constrained', sharey=True)\nax1.plot(x, np.cos(6*x) * np.exp(-x))\nax1.set_title('damped')\nax1.set_xlabel('time (s)')\nax1.set_ylabel('amplitude')\n\nax2.plot(x, np.cos(6*x))\nax2.set_xlabel('time (s)')\nax2.set_title('undamped')\n\nfig.suptitle('Different types of oscillations', fontsize=16)\n\nplt.show()"}]},{"title":"Add global x- and y-labels to a figure","body":["Add global x- and y-labels to a figure","Next, we will add global x- and y-labels to a figure showing the relative stock prices of different companies over time. We will use the np.genfromtxt() function to read in a CSV file containing stock price data and then plot the data for each company using subplots. We will use the fig.supxlabel() and fig.supylabel() methods to add global x- and y-labels to the figure."],"code":[{"lang":"python","text":"from matplotlib.cbook import get_sample_data\n\nwith get_sample_data('Stocks.csv') as file:\n    stocks = np.genfromtxt(\n        file, delimiter=',', names=True, dtype=None,\n        converters={0: lambda x: np.datetime64(x, 'D')}, skip_header=1)\n\nfig, axs = plt.subplots(4, 2, figsize=(9, 5), layout='constrained',\n                        sharex=True, sharey=True)\nfor nn, ax in enumerate(axs.flat):\n    column_name = stocks.dtype.names[1+nn]\n    y = stocks[column_name]\n    line, = ax.plot(stocks['Date'], y / np.nanmax(y), lw=2.5)\n    ax.set_title(column_name, fontsize='small', loc='left')\nfig.supxlabel('Year')\nfig.supylabel('Stock price relative to max')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from matplotlib.cbook import get_sample_data\n\nwith get_sample_data('Stocks.csv') as file:\n    stocks = np.genfromtxt(\n        file, delimiter=',', names=True, dtype=None,\n        converters={0: lambda x: np.datetime64(x, 'D')}, skip_header=1)\n\nfig, axs = plt.subplots(4, 2, figsize=(9, 5), layout='constrained',\n                        sharex=True, sharey=True)\nfor nn, ax in enumerate(axs.flat):\n    column_name = stocks.dtype.names[1+nn]\n    y = stocks[column_name]\n    line, = ax.plot(stocks['Date'], y / np.nanmax(y), lw=2.5)\n    ax.set_title(column_name, fontsize='small', loc='left')\nfig.supxlabel('Year')\nfig.supylabel('Stock price relative to max')\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-filled-polygon-with-matplotlib":{"intro":"In this lab, we will learn how to create a filled polygon using Matplotlib in Python. We will use the Koch snowflake as an example polygon.","steps":[{"title":"Import Libraries","body":["Before we start, let's import the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the Koch Snowflake Function","body":["Define the Koch Snowflake Function","Next, we will define a function to generate the Koch snowflake. The function takes two parameters: the recursion depth and the scale factor."],"code":[{"lang":"python","text":"def koch_snowflake(order, scale=10):\n    \"\"\"\n    Return two lists x, y of point coordinates of the Koch snowflake.\n\n    Parameters\n    ----------\n    order : int\n        The recursion depth.\n    scale : float\n        The extent of the snowflake (edge length of the base triangle).\n    \"\"\"\n    def _koch_snowflake_complex(order):\n        if order == 0:\n            # initial triangle\n            angles = np.array([0, 120, 240]) + 90\n            return scale / np.sqrt(3) * np.exp(np.deg2rad(angles) * 1j)\n        else:\n            ZR = 0.5 - 0.5j * np.sqrt(3) / 3\n\n            p1 = _koch_snowflake_complex(order - 1)  # start points\n            p2 = np.roll(p1, shift=-1)  # end points\n            dp = p2 - p1  # connection vectors\n\n            new_points = np.empty(len(p1) * 4, dtype=np.complex128)\n            new_points[::4] = p1\n            new_points[1::4] = p1 + dp / 3\n            new_points[2::4] = p1 + dp * ZR\n            new_points[3::4] = p1 + dp / 3 * 2\n            return new_points\n\n    points = _koch_snowflake_complex(order)\n    x, y = points.real, points.imag\n    return x, y"}]},{"title":"Generate a Filled Polygon","body":["Now, we can generate a filled polygon using the fill() function. We will use the Koch snowflake function to generate the coordinates for the polygon."],"code":[{"lang":"python","text":"x, y = koch_snowflake(order=5)\n\nplt.figure(figsize=(8, 8))\nplt.axis('equal')\nplt.fill(x, y)\nplt.show()"}]},{"title":"Customize the Polygon","body":["We can customize the colors and linewidth of the polygon using keyword arguments in the fill() function."],"code":[{"lang":"python","text":"x, y = koch_snowflake(order=2)\n\nfig, (ax1, ax2, ax3) = plt.subplots(1, 3, figsize=(9, 3),\n                                    subplot_kw={'aspect': 'equal'})\nax1.fill(x, y)\nax2.fill(x, y, facecolor='lightsalmon', edgecolor='orangered', linewidth=3)\nax3.fill(x, y, facecolor='none', edgecolor='purple', linewidth=3)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"x, y = koch_snowflake(order=2)\n\nfig, (ax1, ax2, ax3) = plt.subplots(1, 3, figsize=(9, 3),\n                                    subplot_kw={'aspect': 'equal'})\nax1.fill(x, y)\nax2.fill(x, y, facecolor='lightsalmon', edgecolor='orangered', linewidth=3)\nax3.fill(x, y, facecolor='none', edgecolor='purple', linewidth=3)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-fill-between-and-alpha":{"intro":"In data visualization, sometimes it is necessary to highlight certain areas or ranges on a graph. The fill_between function of Matplotlib is a useful tool for generating a shaded region between a minimum and maximum boundary. It can also be used to enhance the visual appearance of a graph. The alpha argument can be used to adjust the transparency of the shaded region. This lab will guide you through several examples of using fill_between and alpha in Matplotlib to create more visually appealing and informative graphs.","steps":[{"title":"Enhancing a Line Plot with fill_between","body":["Enhancing a Line Plot with fill_between","The first example demonstrates how to enhance a line plot with fill_between. We will use financial data from Google to create two subplots, one with a simple line plot and the other with a filled line plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.cbook as cbook\n\n# load up some sample financial data\nr = cbook.get_sample_data('goog.npz')['price_data'].view(np.recarray)\n\n# create two subplots with the shared x and y axes\nfig, (ax1, ax2) = plt.subplots(1, 2, sharex=True, sharey=True)\n\npricemin = r.close.min()\n\nax1.plot(r.date, r.close, lw=2)\nax2.fill_between(r.date, pricemin, r.close, alpha=0.7)\n\nfor ax in ax1, ax2:\n    ax.grid(True)\n    ax.label_outer()\n\nax1.set_ylabel('price')\nfig.suptitle('Google (GOOG) daily closing price')\nfig.autofmt_xdate()"}]},{"title":"Using alpha to Soften Colors","body":["The alpha argument can also be used to soften colors for more visually appealing plots. In the following example, we will compute two populations of random walkers with a different mean and standard deviation of the normal distributions from which the steps are drawn. We use filled regions to plot +/- one standard deviation of the mean position of the population."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nNsteps, Nwalkers = 100, 250\nt = np.arange(Nsteps)\n\n# an (Nsteps x Nwalkers) array of random walk steps\nS1 = 0.004 + 0.02*np.random.randn(Nsteps, Nwalkers)\nS2 = 0.002 + 0.01*np.random.randn(Nsteps, Nwalkers)\n\n# an (Nsteps x Nwalkers) array of random walker positions\nX1 = S1.cumsum(axis=0)\nX2 = S2.cumsum(axis=0)\n\n# Nsteps length arrays empirical means and standard deviations of both\n# populations over time\nmu1 = X1.mean(axis=1)\nsigma1 = X1.std(axis=1)\nmu2 = X2.mean(axis=1)\nsigma2 = X2.std(axis=1)\n\n# plot it!\nfig, ax = plt.subplots(1)\nax.plot(t, mu1, lw=2, label='mean population 1')\nax.plot(t, mu2, lw=2, label='mean population 2')\nax.fill_between(t, mu1+sigma1, mu1-sigma1, facecolor='C0', alpha=0.4)\nax.fill_between(t, mu2+sigma2, mu2-sigma2, facecolor='C1', alpha=0.4)\nax.set_title(r'random walkers empirical $\\mu$ and $\\pm \\sigma$ interval')\nax.legend(loc='upper left')\nax.set_xlabel('num steps')\nax.set_ylabel('position')\nax.grid()"}]},{"title":"Highlighting Certain Regions with where","body":["Highlighting Certain Regions with where","The where keyword argument is very handy for highlighting certain regions of the graph. where takes a boolean mask the same length as the x, ymin and ymax arguments, and only fills in the region where the boolean mask is True. In the example below, we simulate a single random walker and compute the analytic mean and standard deviation of the population positions. The population mean is shown as the dashed line, and the plus/minus one sigma deviation from the mean is shown as the filled region. We use the where mask X > upper_bound to find the region where the walker is outside the one sigma boundary, and shade that region red."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(1)\n\nNsteps = 500\nt = np.arange(Nsteps)\n\nmu = 0.002\nsigma = 0.01\n\n# the steps and position\nS = mu + sigma*np.random.randn(Nsteps)\nX = S.cumsum()\n\n# the 1 sigma upper and lower analytic population bounds\nlower_bound = mu*t - sigma*np.sqrt(t)\nupper_bound = mu*t + sigma*np.sqrt(t)\n\nfig, ax = plt.subplots(1)\nax.plot(t, X, lw=2, label='walker position')\nax.plot(t, mu*t, lw=1, label='population mean', color='C0', ls='--')\nax.fill_between(t, lower_bound, upper_bound, facecolor='C0', alpha=0.4,\n                label='1 sigma range')\nax.legend(loc='upper left')\n\n# here we use the where argument to only fill the region where the\n# walker is above the population 1 sigma boundary\nax.fill_between(t, upper_bound, X, where=X > upper_bound, fc='red', alpha=0.4)\nax.fill_between(t, lower_bound, X, where=X < lower_bound, fc='red', alpha=0.4)\nax.set_xlabel('num steps')\nax.set_ylabel('position')\nax.grid()"}]},{"title":"Highlighting Spans of an Axes with axhspan and axvspan","body":["Highlighting Spans of an Axes with axhspan and axvspan","Another handy use of filled regions is to highlight horizontal or vertical spans of an Axes. For that Matplotlib has the helper functions axhspan and axvspan. See the axhspan_demo gallery for more information."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig, ax = plt.subplots()\n\nax.axhspan(0.25, 0.75, facecolor='0.5', alpha=0.5)\nax.axvspan(6, 7, facecolor='r', alpha=0.5)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nfig, ax = plt.subplots()\n\nax.axhspan(0.25, 0.75, facecolor='0.5', alpha=0.5)\nax.axvspan(6, 7, facecolor='r', alpha=0.5)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-fill-between":{"intro":"Matplotlib is a data visualization library in Python programming language. It is used to create static, animated, and interactive visualizations in Python. In this lab, you will learn how to use fill_between function from Matplotlib to fill the area between two lines.","steps":[{"title":"Basic Usage","body":["The fill_between function can be used to fill the area between two lines. The parameters _y1_ and _y2_ can be scalars, indicating a horizontal boundary at the given y-values. If only _y1_ is given, _y2_ defaults to 0."],"code":[{"lang":"python","text":"x = np.arange(0.0, 2, 0.01)\ny1 = np.sin(2 * np.pi * x)\ny2 = 0.8 * np.sin(4 * np.pi * x)\n\nfig, (ax1, ax2, ax3) = plt.subplots(3, 1, sharex=True, figsize=(6, 6))\n\nax1.fill_between(x, y1)\nax1.set_title('fill between y1 and 0')\n\nax2.fill_between(x, y1, 1)\nax2.set_title('fill between y1 and 1')\n\nax3.fill_between(x, y1, y2)\nax3.set_title('fill between y1 and y2')\nax3.set_xlabel('x')\nfig.tight_layout()"}]},{"title":"Confidence Bands","body":["A common application for fill_between is the indication of confidence bands. fill_between uses the colors of the color cycle as the fill color. It is therefore often a good practice to lighten the color by making the area semi-transparent using _alpha_."],"code":[{"lang":"python","text":"N = 21\nx = np.linspace(0, 10, 11)\ny = [3.9, 4.4, 10.8, 10.3, 11.2, 13.1, 14.1,  9.9, 13.9, 15.1, 12.5]\n\n# fit a linear curve and estimate its y-values and their error.\na, b = np.polyfit(x, y, deg=1)\ny_est = a * x + b\ny_err = x.std() * np.sqrt(1/len(x) +\n                          (x - x.mean())**2 / np.sum((x - x.mean())**2))\n\nfig, ax = plt.subplots()\nax.plot(x, y_est, '-')\nax.fill_between(x, y_est - y_err, y_est + y_err, alpha=0.2)\nax.plot(x, y, 'o', color='tab:brown')"}]},{"title":"Selectively Filling Horizontal Regions","body":["Selectively Filling Horizontal Regions","The parameter _where_ allows to specify the x-ranges to fill. It's a boolean array with the same size as _x_. Only x-ranges of contiguous _True_ sequences are filled. As a result, the range between neighboring _True_ and _False_ values is never filled. It is therefore recommended to set interpolate=True unless the x-distance of the data points is fine enough so that the above effect is not noticeable."],"code":[{"lang":"python","text":"x = np.array([0, 1, 2, 3])\ny1 = np.array([0.8, 0.8, 0.2, 0.2])\ny2 = np.array([0, 0, 1, 1])\n\nfig, (ax1, ax2) = plt.subplots(2, 1, sharex=True)\n\nax1.set_title('interpolation=False')\nax1.plot(x, y1, 'o--')\nax1.plot(x, y2, 'o--')\nax1.fill_between(x, y1, y2, where=(y1 > y2), color='C0', alpha=0.3)\nax1.fill_between(x, y1, y2, where=(y1 < y2), color='C1', alpha=0.3)\n\nax2.set_title('interpolation=True')\nax2.plot(x, y1, 'o--')\nax2.plot(x, y2, 'o--')\nax2.fill_between(x, y1, y2, where=(y1 > y2), color='C0', alpha=0.3,\n                 interpolate=True)\nax2.fill_between(x, y1, y2, where=(y1 <= y2), color='C1', alpha=0.3,\n                 interpolate=True)\nfig.tight_layout()"}]},{"title":"Selectively Marking Horizontal Regions Across the Whole Axes","body":["Selectively Marking Horizontal Regions Across the Whole Axes","The same selection mechanism can be applied to fill the full vertical height of the axes. To be independent of y-limits, we add a transform that interprets the x-values in data coordinates and the y-values in axes coordinates. The following example marks the regions in which the y-data are above a given threshold."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nx = np.arange(0, 4 * np.pi, 0.01)\ny = np.sin(x)\nax.plot(x, y, color='black')\n\nthreshold = 0.75\nax.axhline(threshold, color='green', lw=2, alpha=0.7)\nax.fill_between(x, 0, 1, where=y > threshold,\n                color='green', alpha=0.5, transform=ax.get_xaxis_transform())"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nx = np.arange(0, 4 * np.pi, 0.01)\ny = np.sin(x)\nax.plot(x, y, color='black')\n\nthreshold = 0.75\nax.axhline(threshold, color='green', lw=2, alpha=0.7)\nax.fill_between(x, 0, 1, where=y > threshold,\n                color='green', alpha=0.5, transform=ax.get_xaxis_transform())"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-fill-betweenx":{"intro":"Matplotlib is a data visualization library in Python. It provides a wide variety of tools to create complex and customizable plots, charts, and graphs. One of the most useful tools provided by Matplotlib is the fill_betweenx function. This function is used to fill the area between two horizontal curves. In this tutorial, we will explore the fill_betweenx function and learn how to use it to create different types of plots.","steps":[{"title":"Plotting Simple Fill Betweenx","body":["In this step, we will learn how to use the fill_betweenx function to create a simple plot. We will fill the area between two curves."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\ny = np.arange(0.0, 2, 0.01)\nx1 = np.sin(2 * np.pi * y)\nx2 = 1.2 * np.sin(4 * np.pi * y)\n\nfig, ax = plt.subplots(figsize=(6, 6))\n\nax.fill_betweenx(y, x1, x2, color='green', alpha=0.5)\nax.plot(x1, y, color='blue')\nax.plot(x2, y, color='red')\n\nplt.show()"}]},{"title":"Creating Multiple Subplots","body":["In this step, we will learn how to create multiple subplots and use the fill_betweenx function to fill the area between two horizontal curves in each subplot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\ny = np.arange(0.0, 2, 0.01)\nx1 = np.sin(2 * np.pi * y)\nx2 = 1.2 * np.sin(4 * np.pi * y)\n\nfig, [ax1, ax2, ax3] = plt.subplots(1, 3, sharey=True, figsize=(12, 4))\n\nax1.fill_betweenx(y, 0, x1, color='green', alpha=0.5)\nax1.plot(x1, y, color='blue')\nax1.set_title('Fill between (x1, 0)')\n\nax2.fill_betweenx(y, x1, 1, color='red', alpha=0.5)\nax2.plot(x1, y, color='blue')\nax2.set_title('Fill between (x1, 1)')\n\nax3.fill_betweenx(y, x1, x2, color='orange', alpha=0.5)\nax3.plot(x1, y, color='blue')\nax3.plot(x2, y, color='red')\nax3.set_title('Fill between (x1, x2)')\n\nplt.show()"}]},{"title":"Using Logical Conditions","body":["In this step, we will learn how to use logical conditions to fill the area between two horizontal curves."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\ny = np.arange(0.0, 2, 0.01)\nx1 = np.sin(2 * np.pi * y)\nx2 = 1.2 * np.sin(4 * np.pi * y)\n\nfig, ax = plt.subplots(figsize=(6, 6))\n\nax.plot(x1, y, color='black')\nax.plot(x2, y, color='black')\n\nax.fill_betweenx(y, x1, x2, where=x2 >= x1, facecolor='green', alpha=0.5)\nax.fill_betweenx(y, x1, x2, where=x2 <= x1, facecolor='red', alpha=0.5)\n\nplt.show()"}]},{"title":"Using Masked Arrays","body":["In this step, we will learn how to use masked arrays to fill the area between two horizontal curves."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\ny = np.arange(0.0, 2, 0.01)\nx1 = np.sin(2 * np.pi * y)\nx2 = 1.2 * np.sin(4 * np.pi * y)\nx2 = np.ma.masked_greater(x2, 1.0)\n\nfig, ax = plt.subplots(figsize=(6, 6))\n\nax.plot(x1, y, color='black')\nax.plot(x2, y, color='black')\n\nax.fill_betweenx(y, x1, x2, where=x2 >= x1, facecolor='green', alpha=0.5)\nax.fill_betweenx(y, x1, x2, where=x2 <= x1, facecolor='red', alpha=0.5)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\ny = np.arange(0.0, 2, 0.01)\nx1 = np.sin(2 * np.pi * y)\nx2 = 1.2 * np.sin(4 * np.pi * y)\nx2 = np.ma.masked_greater(x2, 1.0)\n\nfig, ax = plt.subplots(figsize=(6, 6))\n\nax.plot(x1, y, color='black')\nax.plot(x2, y, color='black')\n\nax.fill_betweenx(y, x1, x2, where=x2 >= x1, facecolor='green', alpha=0.5)\nax.fill_betweenx(y, x1, x2, where=x2 <= x1, facecolor='red', alpha=0.5)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-spiral-plot-with-python-and-matplotli":{"intro":"In this lab, we will use Python and Matplotlib to create a fill spiral plot. We will use the numpy and matplotlib.pyplot libraries to generate the plot.","steps":[{"title":"Import libraries","body":["We will import the necessary libraries to generate the plot. We will use numpy for numerical calculations and matplotlib.pyplot for creating the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define variables","body":["We will define the variables theta, a, and b for our plot."],"code":[{"lang":"python","text":"theta = np.arange(0, 8*np.pi, 0.1)\na = 1\nb = .2"}]},{"title":"Generate the plot","body":["We will generate the plot by looping through four values of dt and concatenating the resulting x and y arrays."],"code":[{"lang":"python","text":"for dt in np.arange(0, 2*np.pi, np.pi/2.0):\n\n    x = a*np.cos(theta + dt)*np.exp(b*theta)\n    y = a*np.sin(theta + dt)*np.exp(b*theta)\n\n    dt = dt + np.pi/4.0\n\n    x2 = a*np.cos(theta + dt)*np.exp(b*theta)\n    y2 = a*np.sin(theta + dt)*np.exp(b*theta)\n\n    xf = np.concatenate((x, x2[::-1]))\n    yf = np.concatenate((y, y2[::-1]))\n\n    p1 = plt.fill(xf, yf)\n\nplt.show()"}]},{"title":"Interpretation","body":["The plot generated by the code shows a spiral that is filled with color. The a and b variables control the shape of the spiral, while the theta variable controls the number of revolutions. The loop through dt allows us to create a spiral with four \"arms\" by rotating the plot by 45 degrees each time."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-hatch-filled-histograms-with-matplotl":{"intro":"In this lab, we will learn how to create hatch-filled histograms using Matplotlib. A histogram is a graphical representation of data that uses bars to show the frequency of numerical data. A hatch-filled histogram is a histogram in which the bars are filled with a pattern of lines, dots, or other symbols.","steps":[{"title":"Import necessary libraries","body":["We will import the necessary libraries for this lab. We need the following libraries:","• numpy for generating random data • matplotlib.pyplot for creating plots • matplotlib.ticker for setting axis tick locations • cycler for creating style cycles • functools.partial for creating a partial function"],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mticker\nfrom cycler import cycler\nfrom functools import partial"}]},{"title":"Define the histogram function","body":["We will define a function to draw a histogram as a stepped patch. The function will take the following parameters:","• ax: the Axes to plot to • edges: a length n+1 array giving the left edges of each bin and the right edge of the last bin • values: a length n array of bin counts or values • bottoms: a float or array, optional, a length n array of the bottom of the bars. If None, zero is used. • orientation: a string, optional, the orientation of the histogram. 'v' (default) has the bars increasing in the positive y-direction."],"code":[{"lang":"python","text":"def filled_hist(ax, edges, values, bottoms=None, orientation='v', **kwargs):\n    \"\"\"\n    Draw a histogram as a stepped patch.\n\n    Parameters\n    ----------\n    ax : Axes\n        The axes to plot to\n\n    edges : array\n        A length n+1 array giving the left edges of each bin and the\n        right edge of the last bin.\n\n    values : array\n        A length n array of bin counts or values\n\n    bottoms : float or array, optional\n        A length n array of the bottom of the bars.  If None, zero is used.\n\n    orientation : {'v', 'h'}\n       Orientation of the histogram.  'v' (default) has\n       the bars increasing in the positive y-direction.\n\n    **kwargs\n        Extra keyword arguments are passed through to `.fill_between`.\n\n    Returns\n    -------\n    ret : PolyCollection\n        Artist added to the Axes\n    \"\"\"\n    if orientation not in 'hv':\n        raise ValueError(f\"orientation must be in {{'h', 'v'}} not {orientation}\")\n\n    kwargs.setdefault('step', 'post')\n    kwargs.setdefault('alpha', 0.7)\n    edges = np.asarray(edges)\n    values = np.asarray(values)\n    if len(edges) - 1 != len(values):\n        raise ValueError(f'Must provide one more bin edge than value not: {len(edges)=} {len(values)=}')\n\n    if bottoms is None:\n        bottoms = 0\n    bottoms = np.broadcast_to(bottoms, values.shape)\n\n    values = np.append(values, values[-1])\n    bottoms = np.append(bottoms, bottoms[-1])\n    if orientation == 'h':"}]},{"title":"Define the stacked histogram function","body":["Define the stacked histogram function","We will define a function to create a stacked histogram. The function will take the following parameters:","• ax: the axes to add artists to • stacked_data: a (M, N) shaped array. The first dimension will be iterated over to compute histograms row-wise • sty_cycle: a Cycler or operable of dict, style to apply to each set • bottoms: an array, default: 0, the initial positions of the bottoms. • hist_func: a callable, optional. Must have signature bin_vals, bin_edges = f(data). bin_edges expected to be one longer than bin_vals • labels: a list of strings, optional, the label for each set. If not given and stacked data is an array defaults to 'default set {n}'. If stacked_data is a mapping and labels is None, default to the keys. If…"],"code":[{"lang":"python","text":"def stack_hist(ax, stacked_data, sty_cycle, bottoms=None, hist_func=None, labels=None, plot_func=None, plot_kwargs=None):\n    \"\"\"\n    Parameters\n    ----------\n    ax : axes.Axes\n        The axes to add artists too\n\n    stacked_data : array or Mapping\n        A (M, N) shaped array.  The first dimension will be iterated over to\n        compute histograms row-wise\n\n    sty_cycle : Cycler or operable of dict\n        Style to apply to each set\n\n    bottoms : array, default: 0\n        The initial positions of the bottoms.\n\n    hist_func : callable, optional\n        Must have signature `bin_vals, bin_edges = f(data)`.\n        `bin_edges` expected to be one longer than `bin_vals`\n\n    labels : list of str, optional\n        The label for each set.\n\n        If not given and stacked data is an array defaults to 'default set {n}'\n\n        If *stacked_data* is a mapping, and *labels* is None, default to the\n        keys.\n\n        If *stacked_data* is a mapping and *labels* is given then only the\n        columns listed will be plotted.\n\n    plot_func : callable, optional\n        Function to call to draw the histogram must have signature:\n\n          ret = plot_func(ax, edges, top, bottoms=bottoms,\n                          label=label, **kwargs)\n\n    plot_kwargs : dict, optional\n        Any extra keyword arguments to pass through to the plotting function.\n        This will be the same for all calls to the plotting function and will\n        override the values in *sty_cycle*.\n\n    Returns\n    -------\n    arts : dict\n        Dictionary of artists keyed on their labels\n    \"\"\""}]},{"title":"Set up histogram function to fixed bins","body":["Set up histogram function to fixed bins","We will set up a histogram function with fixed bins using numpy.histogram. We will create 20 bins ranging from -3 to 3."],"code":[{"lang":"python","text":"edges = np.linspace(-3, 3, 20, endpoint=True)\nhist_func = partial(np.histogram, bins=edges)"}]},{"title":"Set up style cycles","body":["We will set up style cycles for the histograms using cycler. We will create three style cycles: one for the facecolor, one for the label, and one for the hatch pattern."],"code":[{"lang":"python","text":"color_cycle = cycler(facecolor=plt.rcParams['axes.prop_cycle'][:4])\nlabel_cycle = cycler(label=[f'set {n}' for n in range(4)])\nhatch_cycle = cycler(hatch=['/', '*', '+', '|'])"}]},{"title":"Generate random data","body":["We will generate random data using numpy.random.randn. We will generate 4 sets of data with 12250 points each."],"code":[{"lang":"python","text":"np.random.seed(19680801)\nstack_data = np.random.randn(4, 12250)"}]},{"title":"Create the hatch-filled histogram","body":["Create the hatch-filled histogram","We will create a hatch-filled histogram using the stack_hist function we defined earlier. We will use the stack_data, color_cycle, and hist_func we defined earlier. We will also set plot_kwargs to include edgecolor and orientation."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(9, 4.5), tight_layout=True)\narts = stack_hist(ax1, stack_data, color_cycle + label_cycle + hatch_cycle, hist_func=hist_func)\n\narts = stack_hist(ax2, stack_data, color_cycle, hist_func=hist_func, plot_kwargs=dict(edgecolor='w', orientation='h'))\nax1.set_ylabel('counts')\nax1.set_xlabel('x')\nax2.set_xlabel('counts')\nax2.set_ylabel('x')"}]},{"title":"Create the labeled hatch-filled histogram","body":["Create the labeled hatch-filled histogram","We will create a labeled hatch-filled histogram using the stack_hist function we defined earlier. We will use the dict_data, color_cycle, and hist_func we defined earlier. We will also set labels to ['set 0', 'set 3'] to plot only the first and last set."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(9, 4.5), tight_layout=True, sharey=True)\ndict_data = dict(zip((c['label'] for c in label_cycle), stack_data))\narts = stack_hist(ax1, dict_data, color_cycle + hatch_cycle, hist_func=hist_func)\n\narts = stack_hist(ax2, dict_data, color_cycle + hatch_cycle, hist_func=hist_func, labels=['set 0', 'set 3'])\nax1.xaxis.set_major_locator(mticker.MaxNLocator(5))\nax1.set_xlabel('counts')\nax1.set_ylabel('x')\nax2.set_ylabel('x')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(9, 4.5), tight_layout=True, sharey=True)\ndict_data = dict(zip((c['label'] for c in label_cycle), stack_data))\narts = stack_hist(ax1, dict_data, color_cycle + hatch_cycle, hist_func=hist_func)\n\narts = stack_hist(ax2, dict_data, color_cycle + hatch_cycle, hist_func=hist_func, labels=['set 0', 'set 3'])\nax1.xaxis.set_major_locator(mticker.MaxNLocator(5))\nax1.set_xlabel('counts')\nax1.set_ylabel('x')\nax2.set_ylabel('x')"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-python-matplotlib-plotting-basics":{"intro":"This tutorial will guide you through the basics of Python Matplotlib, a plotting library for the Python programming language. In this tutorial, you will learn how to create and customize different types of plots using Matplotlib.","steps":[{"title":"Installation","body":[],"code":[{"lang":"shell","text":"pip install matplotlib"}]},{"title":"Importing Matplotlib","body":["To use Matplotlib, you need to import it in your Python script. You can import Matplotlib using the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Creating a Simple Plot","body":["The most basic plot in Matplotlib is a line plot. You can create a line plot using the plot() method. Here's an example code that creates a simple line plot:","In this code, we first define our data points as two lists x and y. We then create a plot using the plot() method and pass in our data points. We then add labels to the X and Y axes and a title to the plot using the xlabel(), ylabel(), and title() methods. Finally, we display the plot using the show() method."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# Data\nx = [1, 2, 3, 4, 5]\ny = [2, 4, 6, 8, 10]\n\n# Create a plot\nplt.plot(x, y)\n\n# Add labels and title\nplt.xlabel('X-axis')\nplt.ylabel('Y-axis')\nplt.title('Simple Plot')\n\n# Display the plot\nplt.show()"}]},{"title":"Customizing the Plot","body":["Matplotlib offers a wide range of customization options for plots. Here's an example code that customizes our simple line plot:","In this code, we use various parameters of the plot() method to customize the plot. We change the color of the line to red, the linewidth to 2, the linestyle to dashed (--), the marker to a circle (o), the markersize to 8, and the markerfacecolor to yellow."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# Data\nx = [1, 2, 3, 4, 5]\ny = [2, 4, 6, 8, 10]\n\n# Create a plot\nplt.plot(x, y, color='red', linewidth=2, linestyle='--', marker='o', markersize=8, markerfacecolor='yellow')\n\n# Add labels and title\nplt.xlabel('X-axis')\nplt.ylabel('Y-axis')\nplt.title('Customized Plot')\n\n# Display the plot\nplt.show()"}]},{"title":"Creating Different Types of Plots","body":["Creating Different Types of Plots","Matplotlib supports a wide range of plot types, including line plots, scatter plots, bar plots, and more. Here's an example code that creates a scatter plot:","In this code, we use the scatter() method to create a scatter plot. We generate some random data using the NumPy library and pass it to the scatter() method. We also use the c parameter to specify the colors of the data points, the s parameter to specify the sizes of the data points, and the alpha parameter to specify the transparency of the data points."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Generate some random data\nx = np.random.rand(50)\ny = np.random.rand(50)\ncolors = np.random.rand(50)\nsizes = 1000 * np.random.rand(50)\n\n# Create a scatter plot\nplt.scatter(x, y, c=colors, s=sizes, alpha=0.5)\n\n# Add labels and title\nplt.xlabel('X-axis')\nplt.ylabel('Y-axis')\nplt.title('Scatter Plot')\n\n# Display the plot\nplt.show()"}]}],"commands":["pip install matplotlib"],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Generate some random data\nx = np.random.rand(50)\ny = np.random.rand(50)\ncolors = np.random.rand(50)\nsizes = 1000 * np.random.rand(50)\n\n# Create a scatter plot\nplt.scatter(x, y, c=colors, s=sizes, alpha=0.5)\n\n# Add labels and title\nplt.xlabel('X-axis')\nplt.ylabel('Y-axis')\nplt.title('Scatter Plot')\n\n# Display the plot\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-logo-creation":{"intro":"This lab will guide you through the process of creating the Firefox logo using Python's Matplotlib library.","steps":[{"title":"Import Required Libraries","body":["We will first import all the required libraries for this project, which include re, matplotlib.pyplot, numpy, matplotlib.patches, and matplotlib.path."],"code":[{"lang":"python","text":"import re\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.patches as patches\nfrom matplotlib.path import Path"}]},{"title":"Define the Firefox Logo Path","body":["We will define the path of the Firefox logo using SVG path data."],"code":[{"lang":"python","text":"firefox = \"M28.4,22.469c0.479-0.964,0.851-1.991,1.095-3.066c0.953-3.661,0.666-6.854,0.666-6.854l-0.327,2.104c0,0-0.469-3.896-1.044-5.353c-0.881-2.231-1.273-2.214-1.274-2.21c0.542,1.379,0.494,2.169,0.483,2.288c-0.01-0.016-0.019-0.032-0.027-0.047c-0.131-0.324-0.797-1.819-2.225-2.878c-2.502-2.481-5.943-4.014-9.745-4.015c-4.056,0-7.705,1.745-10.238,4.525C5.444,6.5,5.183,5.938,5.159,5.317c0,0-0.002,0.002-0.006,0.005c0-0.011-0.003-0.021-0.003-0.031c0,0-1.61,1.247-1.436,4.612c-0.299,0.574-0.56,1.172-0.777,1.791c-0.375,0.817-0.75,2.004-1.059,3.746c0,0,0.133-0.422,0.399-0.988c-0.064,0.482-0.103,0.971-0.116,1.467c-0.09,0.845-0.118,1.865-0.039,3.088c0,0,0.032-0.406,0.136-1.021c0.834,6.854,6.667,12.165,13.743,12.165l0,0c1.86,0,3.636-0.37,5.256-1.036C24.938,27.771,27.116,25.196,28.4,22.469zM16.002,3.356c2.446,0,4.73,0.68,6.68,1.86c-2.274-0.528-3.433-0.261-3.423-0.248c0.013,0.015,3.384,0.589,3.981,1.411c0,0-1.431,0-2.856,0.41c-0.065,0.019,5.242,0.663,6.327,5.966c0,0-0.582-1.213-1.301-1.42c0.473,1.439,0.351,4.17-0.1,5.528c-0.058,0.174-0.118-0.755-1.004-1.155c0.284,2.037-0.018,5.268-1.432,6.158c-0.109,0.07,0.887-3.189,0.201-1.93c-4.093,6.276-8.959,2.539-10.934,1.208c1.585,0.388,3.267,0.108,4.242-0.559c0.982-0.672,1.564-1.162,2.087-1.047c0.522,0.117,0.87-0.407,0.464-0.872c-0.405-0.466-1.392-1.105-2.725-0.757c-0.94,0.247-2.107,1.287-3.886,0.233c-1.518-0.899-1.507-1.63-1.507-2.095c0-0.366,0.257-0.88,0.734-1.028c0.58,0.062,1.044,0.214,1.537,0.466c0.005-0.135,0.006-0.315-0.001-0.519c0.039-0.077,0.015-0.311-0.047-0.596c-0.036-0.287-0.097-0.582-0.19-0.851c0.01-0.002,0.017-0.007,0.021-0.021c0.076-0.344,2.147-1.544,2.299-1.659c0.153-0.114,0.55-0.378,0.506-1.183c-0.015-0.265-0.058-0.294-2.232-0.286c-0.917,0.003-1.425-0.894-1.589-1.245c0.222-1.231,0.863-2.11,1.919-2.704c0.02-0.011,0.015-0.021-0.008-0.027c0.219-0.127-2.524-0.006-3.76,1.604C9.674,8.045,9.219,7.95,8.71,7.95c-0.638,0-1.139,0.07-1.603,0.187c-0.05,0.013-0.122,0.011-0.208-0.001C6.769,8.04,6.575,7.88,6.365,7.672c0.161-0.18,0.324-0.356,0.495-0.526C9.201,4.804,12.43,3.357,16.002,3.356z\"  # noqa"}]},{"title":"Parse SVG Path Data","body":["We will use the svg_parse function to parse the SVG path data into vertices and codes that can be used by Matplotlib."],"code":[{"lang":"python","text":"def svg_parse(path):\n    commands = {'M': (Path.MOVETO,),\n                'L': (Path.LINETO,),\n                'Q': (Path.CURVE3,)*2,\n                'C': (Path.CURVE4,)*3,\n                'Z': (Path.CLOSEPOLY,)}\n    vertices = []\n    codes = []\n    cmd_values = re.split(\"([A-Za-z])\", path)[1:]  # Split over commands.\n    for cmd, values in zip(cmd_values[::2], cmd_values[1::2]):\n        # Numbers are separated either by commas, or by +/- signs (but not at\n        # the beginning of the string).\n        points = ([*map(float, re.split(\",|(?<!^)(?=[+-])\", values))] if values\n                  else [(0., 0.)])  # Only for \"z/Z\" (CLOSEPOLY).\n        points = np.reshape(points, (-1, 2))\n        if cmd.islower():\n            points += vertices[-1][-1]\n        codes.extend(commands[cmd.upper()])\n        vertices.append(points)\n    return np.array(codes), np.concatenate(vertices)\n\n# Parse the Firefox logo path data\ncodes, verts = svg_parse(firefox)\npath = Path(verts, codes)"}]},{"title":"Create the Plot","body":["We will now create the plot using Matplotlib by adding two PathPatch objects to the plot. One will be an orange filled shape, while the other will be a white outline."],"code":[{"lang":"python","text":"# Set the plot limits\nxmin, ymin = verts.min(axis=0) - 1\nxmax, ymax = verts.max(axis=0) + 1\n\n# Create the plot\nfig = plt.figure(figsize=(5, 5), facecolor=\"0.75\")  # gray background\nax = fig.add_axes([0, 0, 1, 1], frameon=False, aspect=1,\n                  xlim=(xmin, xmax),  # centering\n                  ylim=(ymax, ymin),  # centering, upside down\n                  xticks=[], yticks=[])  # no ticks\n\n# Add the white outline\nax.add_patch(patches.PathPatch(path, facecolor='none', edgecolor='w', lw=6))\n\n# Add the orange shape\nax.add_patch(patches.PathPatch(path, facecolor='orange', edgecolor='k', lw=2))\n\n# Display the plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Set the plot limits\nxmin, ymin = verts.min(axis=0) - 1\nxmax, ymax = verts.max(axis=0) + 1\n\n# Create the plot\nfig = plt.figure(figsize=(5, 5), facecolor=\"0.75\")  # gray background\nax = fig.add_axes([0, 0, 1, 1], frameon=False, aspect=1,\n                  xlim=(xmin, xmax),  # centering\n                  ylim=(ymax, ymin),  # centering, upside down\n                  xticks=[], yticks=[])  # no ticks\n\n# Add the white outline\nax.add_patch(patches.PathPatch(path, facecolor='none', edgecolor='w', lw=6))\n\n# Add the orange shape\nax.add_patch(patches.PathPatch(path, facecolor='orange', edgecolor='k', lw=2))\n\n# Display the plot\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-basics-creating-line-plots":{"intro":"Matplotlib is a popular data visualization library in Python. It provides an easy-to-use interface for creating a wide range of visualizations, from simple line plots to complex heatmaps. In this lab, we will go through the basics of Matplotlib and create a simple line plot using the 'fivethirtyeight' style sheet.","steps":[{"title":"Import Matplotlib and NumPy Libraries","body":["Import Matplotlib and NumPy Libraries","The first step is to import the Matplotlib and NumPy libraries. NumPy is a fundamental package for scientific computing in Python that provides powerful arrays and linear algebra functions."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Set the Style to 'fivethirtyeight'","body":["Set the Style to \"fivethirtyeight\"","The \"fivethirtyeight\" style sheet replicates the styles from the popular data-driven news website FiveThirtyEight.com. We will use this style sheet for our visualization."],"code":[{"lang":"python","text":"plt.style.use('fivethirtyeight')"}]},{"title":"Create Data for the Line Plot","body":["In this step, we will create data for our line plot. We will use NumPy's linspace function to create an array of evenly spaced values between 0 and 10. We will also generate some random noise using NumPy's random.randn function."],"code":[{"lang":"python","text":"x = np.linspace(0, 10)\nnp.random.seed(19680801)\nnoise = np.random.randn(50)"}]},{"title":"Create a Figure and Axes Objects","body":["Create a Figure and Axes Objects","Next, we will create a figure and axes object using Matplotlib's subplots function. The figure object represents the entire figure and the axes object represents a single plot within the figure."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Plot the Data","body":["In this step, we will plot the data on the axes object using Matplotlib's plot function. We will plot six different lines with different slopes and random noise."],"code":[{"lang":"python","text":"ax.plot(x, np.sin(x) + x + noise)\nax.plot(x, np.sin(x) + 0.5 * x + noise)\nax.plot(x, np.sin(x) + 2 * x + noise)\nax.plot(x, np.sin(x) - 0.5 * x + noise)\nax.plot(x, np.sin(x) - 2 * x + noise)\nax.plot(x, np.sin(x) + noise)"}]},{"title":"Set the Title and Labels","body":["In this step, we will set the title and labels for the plot using the axes object's set_title, set_xlabel, and set_ylabel methods."],"code":[{"lang":"python","text":"ax.set_title(\"'fivethirtyeight' style sheet\")\nax.set_xlabel(\"x\")\nax.set_ylabel(\"y\")"}]},{"title":"Show the Plot","body":["Finally, we will display the plot using Matplotlib's show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-configuring-the-font-family-in-matplotlib":{"intro":"In Matplotlib, it is possible to configure the font family and style used in plots and visualizations. This is useful for ensuring consistency in the appearance of text across multiple plots and for ensuring that text is legible and easy to read. In this lab, we will explore how to configure the font family and style in Matplotlib.","steps":[{"title":"Choose Default Sans-Serif Font","body":["Choose Default Sans-Serif Font","The default font family in Matplotlib is sans-serif. We can choose to use the default font family by setting the font.family parameter to 'sans-serif'. To do this, we can use the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.rcParams[\"font.family\"] = \"sans-serif\""}]},{"title":"Choose Specific Sans-Serif Font","body":["Choose Specific Sans-Serif Font","If we want to use a specific sans-serif font, we can set the font.sans-serif parameter to a list of font names. Matplotlib will attempt to use the first font in the list that is available on the user's system. To do this, we can use the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.rcParams[\"font.family\"] = \"sans-serif\"\nplt.rcParams[\"font.sans-serif\"] = [\"Nimbus Sans\"]"}]},{"title":"Choose Default Monospace Font","body":["The default monospace font in Matplotlib is determined by the operating system. We can choose to use the default monospace font by setting the font.family parameter to 'monospace'. To do this, we can use the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.rcParams[\"font.family\"] = \"monospace\""}]},{"title":"Choose Specific Monospace Font","body":["Choose Specific Monospace Font","If we want to use a specific monospace font, we can set the font.monospace parameter to a list of font names. Matplotlib will attempt to use the first font in the list that is available on the user's system. To do this, we can use the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.rcParams[\"font.family\"] = \"monospace\"\nplt.rcParams[\"font.monospace\"] = [\"FreeMono\"]"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nplt.rcParams[\"font.family\"] = \"monospace\"\nplt.rcParams[\"font.monospace\"] = [\"FreeMono\"]"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"}};
